window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[186]={"id":"186","numero":186,"titre":"Hypersensibilités et allergies chez l'enfant et l'adulte","objectifs":[{"id":"186-1","rang":"B","rubrique":"Physiopathologie","titre":"Connaître la physiopathologie des réactions d’hypersensibilité : allergique et non allergique","contenu":"<p>L'<span class=\"kw-def\">hypersensibilité</span> désigne des symptômes objectifs et reproductibles initiés par exposition à un stimulus défini à des doses tolérées par <span class=\"kw-clinique\">les</span> sujets normaux. Quatre grandes familles à distinguer cliniquement, car les conséquences et le risque pronostique diffèrent radicalement.</p>\n\n      <h5><span class=\"kw-def\">Classification</span> générale des hypersensibilités</h5>\n      <table >\n        <thead><tr><th>Type</th><th>Mécanisme</th><th>Phase de sensibilisation</th><th>Exemples</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>HS immunologique <span class=\"kw-etio\">allergique</span></strong> <em>(= <span class=\"kw-ci\">allergie</span>)</em></td>\n            <td><span class=\"kw-def\">Immunité adaptative</span> (BCR, TCR)</td>\n            <td><strong>Oui</strong> — l'<span class=\"kw-ci\">allergie</span> n'apparaît qu'après une phase de sensibilisation préalable (sauf allergie croisée à des substances de structure très proche)</td>\n            <td>\n              <strong>Non-<span class=\"kw-chiffre\">IgE</span> médiée :</strong> médiée par LT, <span class=\"kw-bio\">éosinophile</span>, <span class=\"kw-chiffre\">IgG</span><br>\n              <strong>IgE-médiée <span class=\"kw-etio\">atopique</span> :</strong> <span class=\"kw-clinique\">allergie alimentaire</span>, <span class=\"kw-clinique\">rhinite</span>, <span class=\"kw-clinique\">asthme</span>, allergies professionnelles<br>\n              <strong>IgE-médiée non-<span class=\"kw-clinique\">atopique</span> :</strong> piqûres d'insectes, helminthes, médicaments\n            </td>\n          </tr>\n          <tr>\n            <td><strong>HS immunologique non-<span class=\"kw-etio\">allergique</span></strong></td>\n            <td><span class=\"kw-def\">Immunité innée</span> non spécifique d'<span class=\"kw-bio\">antigène</span></td>\n            <td><strong>Pas de sensibilisation préalable</strong></td>\n            <td>Réactions à certains <span class=\"kw-ttt\">AINS</span>, <span class=\"kw-ttt\">paracétamol</span> (inhibition COX-1 → ↑ leucotriènes)</td>\n          </tr>\n          <tr>\n            <td><strong>HS non immunologique</strong></td>\n            <td>Mécanismes <span class=\"kw-def\">toxiques</span>, <span class=\"kw-def\">enzymatiques</span> ou <span class=\"kw-def\">pharmacologiques</span> — <span class=\"kw-clinique\">les</span> cellules immunitaires ne sont pas la cible de l'Ag</td>\n            <td><strong>Non</strong></td>\n            <td>Histaminolibérateurs (<span class=\"kw-ttt\">codéine</span>, <span class=\"kw-ttt\">morphine</span>, <span class=\"kw-ttt\">curares</span>, <span class=\"kw-ttt\">produits de contraste iodés</span>, charcuteries, fromages fermentés)</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-ci\">Intolérance</span></strong></td>\n            <td colspan=\"2\">Regroupe HS non-<span class=\"kw-etio\">allergique</span> + HS non-immunologique <em>(par opposition à l'<span class=\"kw-ci\">allergie</span>)</em></td>\n            <td>Lactose, <span class=\"kw-etio\">gluten</span> non cœliaque</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5><span class=\"kw-def\">Classification</span> de Gell &amp; Coombs (HS allergiques)</h5>\n      <table >\n        <thead><tr><th>Type</th><th>Médiateur immunologique</th><th><span class=\"kw-def\">Physiopathologie</span></th><th>Signes cliniques</th><th>Chronologie</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>I — immédiat</strong></td>\n            <td><span class=\"kw-bio\">IgE</span></td>\n            <td><span class=\"kw-chiffre\">IgE</span> spécifiques se fixent sur récepteurs des <span class=\"kw-bio\">mastocytes / basophiles</span> → dégranulation après <span class=\"kw-ttt\">pontage</span> par l'allergène</td>\n            <td><span class=\"kw-clinique\">Choc anaphylactique</span>, <span class=\"kw-clinique\">œdème de Quincke</span>, <span class=\"kw-clinique\">urticaire</span>, bronchospasme, <span class=\"kw-clinique\">hypotension</span></td>\n            <td><span class=\"kw-chiffre\">1–6 h</span> après la prise</td>\n          </tr>\n          <tr>\n            <td><strong>II — cytotoxique</strong></td>\n            <td><span class=\"kw-bio\">IgG + complément</span></td>\n            <td><span class=\"kw-chiffre\">IgG</span>/IgM reconnaissent un Ag fixé sur cellule cible → activation <span class=\"kw-bio\">complément</span> + phagocytose → destruction cellulaire</td>\n            <td><span class=\"kw-clinique\">Cytopénie médicamenteuse</span> (TIH, agranulocytose, anémie hémolytique immuno-<span class=\"kw-etio\">allergique</span>), allo-immunisation fœtomaternelle ou post-transfusionnelle</td>\n            <td><span class=\"kw-chiffre\">5–15 j</span> après le début du traitement</td>\n          </tr>\n          <tr>\n            <td><strong>III — complexes immuns</strong></td>\n            <td><span class=\"kw-bio\">IgM/IgG + complément ou FcR</span></td>\n            <td>Complexes Ag/Ac solubles circulants → dépôts tissulaires → inflammation + activation <span class=\"kw-bio\">complément</span></td>\n            <td><span class=\"kw-clinique\">Pneumonies d'hypersensibilité</span>, maladie sérique, <span class=\"kw-def\">vascularite</span>, <span class=\"kw-clinique\">urticaire</span></td>\n            <td><span class=\"kw-chiffre\">7–8 j</span> (maladie sérique, <span class=\"kw-clinique\">urticaire</span>) — <span class=\"kw-chiffre\">7–21 j</span> (vascularites)</td>\n          </tr>\n          <tr>\n            <td><strong>IVa — Th1</strong></td>\n            <td><span class=\"kw-bio\">Th1 / IFN-γ</span></td>\n            <td>Inflammation monocytaire</td>\n            <td><span class=\"kw-clinique\">Eczéma de contact</span></td>\n            <td><span class=\"kw-chiffre\">1–21 j</span></td>\n          </tr>\n          <tr>\n            <td><strong>IVb — Th2</strong></td>\n            <td><span class=\"kw-bio\">Th2 / IL-4, IL-5</span></td>\n            <td>Inflammation éosinophilique</td>\n            <td><span class=\"kw-clinique\">EMP</span>, <span class=\"kw-clinique\">DRESS</span></td>\n            <td><strong>EMP :</strong> 1–plusieurs j<br><strong><span class=\"kw-alerte\">DRESS</span> :</strong> <span class=\"kw-alerte\">2–6 semaines</span></td>\n          </tr>\n          <tr>\n            <td><strong>IVc — LT cytotoxiques</strong></td>\n            <td><span class=\"kw-bio\">perforine, granzyme B, FasL</span></td>\n            <td><span class=\"kw-clinique\">Nécrose</span> kératinocytaire par <span class=\"kw-chiffre\">CD4</span>/CD8</td>\n            <td>EMP, <span class=\"kw-alerte\">SJS / Lyell</span>, <span class=\"kw-clinique\">érythème</span> p<span class=\"kw-chiffre\">igm</span>enté fixe</td>\n            <td><strong><span class=\"kw-clinique\">Érythème</span> p<span class=\"kw-chiffre\">igm</span>enté fixe :</strong> 1–2 j<br><strong><span class=\"kw-alerte\">SJS</span>/NET :</strong> <span class=\"kw-alerte\">4–28 j</span></td>\n          </tr>\n          <tr>\n            <td><strong>IVd — neutrophilique</strong></td>\n            <td><span class=\"kw-bio\">LT / IL-8 (CXCL8)</span></td>\n            <td>Inflammation neutrophilique</td>\n            <td><span class=\"kw-clinique\">PEAG</span> (pustulose exanthématique aiguë généralisée)</td>\n            <td><span class=\"kw-chiffre\">1–2 j</span> typiquement</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5><span class=\"kw-def\">Physiopathologie</span> de l'HS immédiate (modèle type I)</h5>\n      <ul>\n        <li><strong>Phase de sensibilisation</strong> <em>(asymptomatique)</em> — 1ère exposition à l'allergène → production d'<span class=\"kw-bio\">IgE spécifiques</span> par <span class=\"kw-clinique\">les</span> LB → fixation des <span class=\"kw-chiffre\">IgE</span> sur leurs récepteurs : <span class=\"kw-bio\">FcεRI</span> (forte affinité) sur <span class=\"kw-bio\">basophiles</span> et mastocytes, <span class=\"kw-bio\">FcεRII</span> (faible affinité) sur <span class=\"kw-bio\">éosinophiles</span>, <span class=\"kw-bio\">monocytes</span>, <span class=\"kw-bio\">plaquettes</span>.</li>\n        <li><strong>2ⁿᵈ <span class=\"kw-def\">contact</span></strong> — réintroduction même en quantité minime → <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">IgE</span> fixées reconnaissent l'allergène et déclenchent la dégranulation. Une sensibilisation ne signifie pas <span class=\"kw-ci\">allergie</span> clinique <em>(tolérance immunitaire possible)</em>.</li>\n        <li><strong>Médiateurs libérés</strong> — pré-formés (<span class=\"kw-bio\">histamine</span>, <span class=\"kw-bio\">tryptase</span>) en minutes → <span class=\"kw-alerte\">anaphylaxie</span> ; néoformés (<span class=\"kw-bio\">prostaglandines</span>, <span class=\"kw-bio\">leucotriènes</span>, cytokines pro-inflammatoires) → phase retardée de l'HS immédiate (≠ type IV).</li>\n        <li><strong>Effets globaux</strong> — <span class=\"kw-clinique\">bronchoconstriction + vasodilatation + extravasation + œdème</span> (sévérité = fonction du lieu et de la quantité libérée).</li>\n        <li><strong>Chronicité</strong> — stimulation prolongée → <span class=\"kw-alerte\">remodelage tissulaire</span> (ex : remodelage bronchique de l'<span class=\"kw-def\">asthme</span>).</li>\n      </ul>\n\n      <h5><span class=\"kw-def\">Physiopathologie</span> de l'HS retardée (modèle <span class=\"kw-clinique\">eczéma</span> de <span class=\"kw-def\">contact</span>, type IVa Th1)</h5>\n      <ul>\n        <li><strong>Phase de sensibilisation</strong> — asymptomatique, dure de quelques jours à plusieurs années. L'haptène pénètre la peau, s'associe à une protéine, est capté par <span class=\"kw-clinique\">les</span> <span class=\"kw-bio\">cellules de Langerhans</span> qui migrent vers les ganglions, maturent et présentent l'Ag aux LT naïfs. Les LT activés deviennent des LT mémoires.</li>\n        <li><strong>Phase de révélation</strong> — survient <span class=\"kw-chiffre\">24–48 h</span> après nouveau <span class=\"kw-def\">contact</span>. <span class=\"kw-clinique\">Les</span> LT mémoires reconnaissent l'Ag, sécrètent des cytokines pro-inflammatoires (IL-2, IL-17, TNF-β, IFN-γ) qui recrutent des cellules mononuclées → <span class=\"kw-clinique\">spongiose</span> et exocytose épidermiques.</li>\n        <li><strong>Haptène</strong> — molécule trop petite pour être immunogène seule, doit se coupler à une <span class=\"kw-def\">protéine porteuse</span> pour induire la sensibilisation.</li>\n      </ul>\n\n      <h5>Concepts fondamentaux à maîtriser</h5>\n      <table >\n        <thead><tr><th>Notion</th><th>Définition</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Atopie</strong></td>\n            <td><span class=\"kw-def\">Prédisposition génétique héréditaire</span> à produire des <span class=\"kw-chiffre\">IgE</span> en réponse à des faibles doses d'allergènes. <span class=\"kw-def\">Facteur de risque</span> de manifestations d'HS immédiate. Maladies atopiques : <span class=\"kw-def\">asthme</span> <span class=\"kw-etio\">allergique</span>, rhino-conjonctivite, <span class=\"kw-clinique\">dermatite</span> <span class=\"kw-clinique\">atopique</span>, <span class=\"kw-ci\">allergie</span> alimentaire IgE-médiée.</td>\n          </tr>\n          <tr>\n            <td><strong>Marche <span class=\"kw-etio\">atopique</span></strong></td>\n            <td>Succession des manifestations atopiques chez un même individu à différents âges : <span class=\"kw-clinique\">dermatite atopique</span> → <span class=\"kw-ci\">allergie</span> alimentaire → <span class=\"kw-clinique\">asthme</span> (<span class=\"kw-chiffre\">3-4 ans</span>) → rhino-conjonctivite (adolescence).</td>\n          </tr>\n          <tr>\n            <td><strong>Allergène</strong></td>\n            <td>Ag induisant une <span class=\"kw-ci\">allergie</span> — <span class=\"kw-def\">protéines ou glycoprotéines</span> d'origine animale ou végétale (<span class=\"kw-clinique\">les</span> glucides comme le lactose et les lipides ne sont pas allergisants).</td>\n          </tr>\n          <tr>\n            <td><strong>Sensibilisation</strong></td>\n            <td>Acquisition d'effecteurs immunitaires (LT et/ou Ig) spécifiques d'un allergène. Objectivée par un test cutané positif. <strong>Ne préjuge pas d'une <span class=\"kw-ci\">allergie</span> clinique</strong> — un sujet sensibilisé asymptomatique reste tolérant.</td>\n          </tr>\n          <tr>\n            <td><strong>Tolérance</strong></td>\n            <td>Absence de symptôme lors de l'exposition à l'allergène, y compris si sensibilisation présente. Repose sur <span class=\"kw-clinique\">les</span> <span class=\"kw-bio\">LT et LB régulateurs</span>. L'<span class=\"kw-ci\">allergie</span> = <span class=\"kw-def\">rupture de la tolérance naturelle</span>.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 187 — <span class=\"kw-ci\">Hypersensibilité</span>, allergies cutanées · 188 — <span class=\"kw-def\">Asthme</span> - Rhinite · 115 — Toxidermies</em></p>","frequence":0},{"id":"186-2","rang":"B","rubrique":"Epidémiologie","titre":"Connaître les grandes tendances épidémiologiques des allergies aux venins d’hyménoptères : prévalence, mortalité","contenu":"<p>L'<span class=\"kw-ci\">allergie</span> aux venins d'<span class=\"kw-def\">hyménoptères</span> est la principale cause de décès par <span class=\"kw-alerte\">anaphylaxie</span> chez l'adulte <strong>après</strong> <span class=\"kw-clinique\">les</span> médicaments. Quatre familles d'hyménoptères à connaître : <span class=\"kw-etio\">abeilles</span>, <span class=\"kw-etio\">guêpes</span>, <span class=\"kw-etio\">frelons</span>, <span class=\"kw-etio\">bourdons</span>.</p>\n\n      <h5>Données chiffrées clés</h5>\n      <table >\n        <thead><tr><th>Paramètre</th><th>Valeur</th><th>Commentaire</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Sensibilisation</strong> (population générale)</td>\n            <td><span class=\"kw-chiffre\">10 à 40 %</span></td>\n            <td>Présence d'<span class=\"kw-chiffre\">IgE</span> spécifiques sans réaction systémique nécessaire</td>\n          </tr>\n          <tr>\n            <td><strong>Réactions systémiques</strong> (population générale)</td>\n            <td><span class=\"kw-chiffre\">0,3 à 7,5 %</span></td>\n            <td>Hétérogénéité géographique forte (rural &gt; urbain, sud &gt; nord)</td>\n          </tr>\n          <tr>\n            <td><strong>Décès par <span class=\"kw-alerte\">anaphylaxie</span></strong></td>\n            <td>2ᵉ cause chez l'adulte</td>\n            <td>Après <span class=\"kw-clinique\">les</span> <span class=\"kw-ttt\">médicaments</span> (1ʳᵉ cause) — devant l'alimentaire chez l'adulte</td>\n          </tr>\n          <tr>\n            <td><strong>Population à risque</strong></td>\n            <td>Adultes &gt; enfants</td>\n            <td>Anaphylaxie aux hyménoptères <span class=\"kw-alerte\">plus fréquente chez l'adulte</span> que chez l'enfant</td>\n          </tr>\n          <tr>\n            <td><strong>Espèce responsable</strong></td>\n            <td><span class=\"kw-etio\">guêpes</span> et <span class=\"kw-etio\">abeilles</span> ++</td>\n            <td><span class=\"kw-clinique\">Les</span> réactions allergiques <span class=\"kw-chiffre\">IgE</span>-médiées sont dues le plus souvent aux piqûres de ces deux espèces</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5>Particularités épidémiologiques</h5>\n      <ul>\n        <li><strong>Sensibilisation ≠ <span class=\"kw-ci\">allergie</span></strong> — la <span class=\"kw-def\">prévalence</span> de sensibilisation (jusqu'à<span class=\"kw-chiffre\"> 40 %</span>) est très supérieure à celle des réactions systémiques (&lt;<span class=\"kw-chiffre\"> 8 %</span>), car la plupart des sujets piqués développent une <span class=\"kw-bio\">tolérance</span> naturelle.</li>\n        <li><strong>Réaction <span class=\"kw-etio\">toxique</span></strong> — distincte de l'<span class=\"kw-ci\">allergie</span> : survient lors de piqûres multiples (essaims) par <span class=\"kw-bio\">effet pharmacologique direct</span> des substances vaso-actives du venin (indépendant du statut <span class=\"kw-etio\">allergique</span>).</li>\n        <li><strong>Mastocytose</strong> — <span class=\"kw-def\">terrain</span> fréquemment associé chez <span class=\"kw-clinique\">les</span> sujets faisant des réactions systémiques sévères → <span class=\"kw-bio\">tryptase basale</span> à doser systématiquement après tout épisode d'<span class=\"kw-alerte\">anaphylaxie</span> aux hyménoptères.</li>\n        <li><strong>Décours évolutif</strong> — la <span class=\"kw-clinique\">sensibilisation persiste typiquement à vie</span>, mais la réactivité clinique peut s'atténuer avec le temps en l'absence de nouvelle piqûre.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>Discriminant à connaître</strong> — l'<span class=\"kw-ci\">allergie</span> aux hyménoptères est la principale cause de décès anaphylactique <strong>chez l'enfant</strong>, mais reste devancée par <span class=\"kw-clinique\">les</span> médicaments chez l'adulte (où elle est <strong>2ᵉ cause</strong>). L'allergie alimentaire est plus fréquente chez l'enfant.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 187 — <span class=\"kw-ci\">Hypersensibilité</span>, allergies cutanées</em></p>","frequence":0},{"id":"186-3","rang":"B","rubrique":"Epidémiologie","titre":"Connaître les grandes tendances épidémiologiques de l’allergie alimentaire : prévalence, mortalité, allergènes","contenu":"<p>L'<span class=\"kw-def\">allergie alimentaire</span> touche <span class=\"kw-chiffre\">5 à 7 %</span> des enfants en France et environ <span class=\"kw-chiffre\">2 %</span> des adultes. Elle est responsable de <span class=\"kw-chiffre\">10 à 40 %</span> des chocs anaphylactiques. Maladie de l'enfance le plus souvent transitoire, mais certaines allergies (arachide, fruits à coque, poissons/crustacés) persistent généralement à vie.</p>\n\n      <h5><span class=\"kw-def\">Prévalence</span> par tranche d'âge</h5>\n      <table >\n        <thead><tr><th>Tranche d'âge</th><th>Prévalence</th><th>Commentaire</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-chiffre\">2–5 ans</span></strong></td><td><span class=\"kw-chiffre\">4 %</span></td><td>Lait, œuf prédominants — <span class=\"kw-clinique\">évolution</span> souvent transitoire</td></tr>\n          <tr><td><strong><span class=\"kw-chiffre\">6–10 ans</span></strong></td><td><span class=\"kw-chiffre\">7 %</span> <em>(pic)</em></td><td>Pic de <span class=\"kw-def\">prévalence</span> pédiatrique — arachide, fruits à coque émergent</td></tr>\n          <tr><td><strong><span class=\"kw-chiffre\">11–14 ans</span></strong></td><td><span class=\"kw-chiffre\">3,5 %</span></td><td>Décrue après guérison des allergies du nourrisson</td></tr>\n          <tr><td><strong>Adulte</strong></td><td><span class=\"kw-chiffre\">2 %</span></td><td>Persistance des allergies réfractaires + allergies de l'adulte (fruits à coque, crustacés)</td></tr>\n          <tr><td><strong>Enfants &lt;<span class=\"kw-chiffre\"> 15 ans</span> (toutes allergies)</strong></td><td><span class=\"kw-chiffre\">30 %</span></td><td>Inclut allergies alimentaires + respiratoires + cutanées</td></tr>\n        </tbody>\n      </table>\n\n      <h5><span class=\"kw-def\">Mortalité</span> et morbidité</h5>\n      <ul>\n        <li><strong>Chocs anaphylactiques d'origine alimentaire</strong> — <span class=\"kw-chiffre\">10 à 40 %</span> de l'ensemble des anaphylaxies.</li>\n        <li><strong>1ʳᵉ cause de décès anaphylactique chez l'enfant</strong> — devant <span class=\"kw-clinique\">les</span> hyménoptères et les médicaments.</li>\n        <li><strong>Allergène le plus mortel</strong> — <span class=\"kw-alerte\">arachide</span> et <span class=\"kw-alerte\">fruits à coque</span> dominent <span class=\"kw-clinique\">les</span> décès anaphylactiques.</li>\n        <li><strong>Augmentation</strong> — <span class=\"kw-def\">incidence</span> en croissance régulière depuis <span class=\"kw-chiffre\">30 ans</span>, parallèlement aux autres maladies atopiques.</li>\n      </ul>\n\n      <h5>Principaux allergènes par âge</h5>\n      <table >\n        <thead><tr><th>Âge</th><th>Allergènes principaux</th><th>Protéines en cause</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>&lt;<span class=\"kw-chiffre\"> 6 mois</span></strong></td>\n            <td><span class=\"kw-etio\">Lait de vache</span></td>\n            <td>Caséine, α-lactalbumine, β-lactoglobuline</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-chiffre\">5–15 mois</span></strong></td>\n            <td><span class=\"kw-etio\">Œuf</span> (le plus fréquent), <span class=\"kw-etio\">arachide</span>, lait de vache, <span class=\"kw-etio\">moutarde</span>, <span class=\"kw-etio\">morue</span></td>\n            <td>Ovalbumine, ovomucoïde (œuf)</td>\n          </tr>\n          <tr>\n            <td><strong>&gt;<span class=\"kw-chiffre\"> 3 ans</span></strong></td>\n            <td><span class=\"kw-etio\">Arachide</span> (cacahuète) <em>en tête</em></td>\n            <td>Ara h 1, Ara h 2, Ara h 3</td>\n          </tr>\n          <tr>\n            <td><strong>Adulte</strong></td>\n            <td><span class=\"kw-etio\">Fruits à coque</span> (pistache, noix de cajou, noisette, noix, amande) ; <span class=\"kw-etio\">fruits</span> (pomme, pêche, abricot, kiwi) ; <span class=\"kw-etio\">crustacés</span> ; <span class=\"kw-etio\">soja</span></td>\n            <td><span class=\"kw-clinique\">PR</span>-10, LTP, tropomyosines</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5><span class=\"kw-clinique\">Évolution</span> naturelle</h5>\n      <ul>\n        <li><strong>Allergies transitoires</strong> — <span class=\"kw-clinique\">APLV</span> et <span class=\"kw-clinique\">allergie à l'œuf</span> guérissent dans <span class=\"kw-chiffre\">~80 %</span> des cas dans <span class=\"kw-clinique\">les</span> premières années.</li>\n        <li><strong>Allergies persistantes</strong> — <span class=\"kw-clinique\">arachide</span> et <span class=\"kw-clinique\">fruits à coque</span> persistent dans <span class=\"kw-chiffre\">~80 %</span> des cas ; <span class=\"kw-clinique\">poissons</span> et <span class=\"kw-clinique\">crustacés</span> persistent le plus souvent.</li>\n        <li><strong>Allergies de l'adulte</strong> — persistent dans le temps, indépendamment du mécanisme.</li>\n      </ul>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 187 — <span class=\"kw-ci\">Hypersensibilité</span>, allergies cutanées · 188 — <span class=\"kw-def\">Asthme</span> - Rhinite</em></p>","frequence":0},{"id":"186-4","rang":"B","rubrique":"Epidémiologie","titre":"Connaître les grandes tendances épidémiologiques des hypersensibilités allergiques et non allergiques médicamenteuses : prévalence, morbidité, mortalité","contenu":"<p><span class=\"kw-clinique\">Les</span> <span class=\"kw-def\">hypersensibilités médicamenteuses</span> touchent environ <span class=\"kw-chiffre\">7 %</span> de la population générale. En France, elles constituent la <strong>1ʳᵉ cause de décès par <span class=\"kw-alerte\">anaphylaxie</span> chez l'adulte</strong>. La déclaration au centre de <span class=\"kw-ttt\">pharmacovigilance</span> est un réflexe obl<span class=\"kw-chiffre\">iga</span>toire devant tout cas suspect.</p>\n\n      <h5>Données chiffrées</h5>\n      <table >\n        <thead><tr><th>Paramètre</th><th>Valeur</th><th>Commentaire</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-def\">Prévalence</span></strong> (population générale)</td>\n            <td><span class=\"kw-chiffre\">~7 %</span></td>\n            <td>Probable surdéclaration — beaucoup d'effets indésirables non immunologiques sont assimilés à tort à des « allergies »</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Mortalité</span> anaphylactique adulte</strong></td>\n            <td>1ʳᵉ cause</td>\n            <td>Devant hyménoptères et alimentaire chez l'adulte</td>\n          </tr>\n          <tr>\n            <td><strong>Mécanismes</strong></td>\n            <td colspan=\"2\">\n              <strong>HS <span class=\"kw-etio\">allergique</span> <span class=\"kw-chiffre\">IgE</span>-médiée :</strong> rare mais grave (<span class=\"kw-alerte\">anaphylaxie</span>) — <span class=\"kw-ttt\">β-lactamines</span> (pénicillines, <span class=\"kw-ttt\">amoxicilline</span>), <span class=\"kw-ttt\">curares</span><br>\n              <strong>HS non immunologique :</strong> mécanisme pharmacologique (<span class=\"kw-ttt\">AINS</span>, <span class=\"kw-ttt\">paracétamol</span> → inhibition COX-1, ↑ leucotriènes)<br>\n              <strong>HS retardée (type IV) :</strong> toxidermies — EMP, <span class=\"kw-alerte\">DRESS</span>, SJS, Lyell, PEAG\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Population à risque</strong></td>\n            <td>Adultes ≫ enfants</td>\n            <td>Allergies médicamenteuses <span class=\"kw-alerte\">rares chez l'adulte</span> et <span class=\"kw-alerte\">encore plus rares chez l'enfant</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5>Principaux médicaments en cause</h5>\n      <table >\n        <thead><tr><th>Famille</th><th>Molécules</th><th>Réaction typique</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Antibiotiques</strong></td>\n            <td><span class=\"kw-ttt\">β-lactamines</span> (pénicillines, <span class=\"kw-ttt\">amoxicilline</span>, céphalosporines injectables)</td>\n            <td><span class=\"kw-chiffre\">IgE</span>-médiée immédiate, <span class=\"kw-alerte\">anaphylaxie</span></td>\n          </tr>\n          <tr>\n            <td><strong>Anti-inflammatoires</strong></td>\n            <td><span class=\"kw-ttt\">AINS</span></td>\n            <td>HS non immunologique (inhibition COX-1) — <em>peut aussi être <span class=\"kw-chiffre\">IgE</span>-médiée chez certains patients</em></td>\n          </tr>\n          <tr>\n            <td><strong>Curares</strong></td>\n            <td><span class=\"kw-ttt\">Suxaméthonium</span> et autres</td>\n            <td>Anaphylaxie peranesthésique — <span class=\"kw-alerte\">2ᵉ cause d'anaphylaxie en anesthésie</span></td>\n          </tr>\n          <tr>\n            <td><strong>Anesthésiques généraux</strong></td>\n            <td>Hypnotiques, <span class=\"kw-ttt\">opioïdes</span></td>\n            <td>Réactions variables, souvent histaminolibération</td>\n          </tr>\n          <tr>\n            <td><strong>Colorants</strong></td>\n            <td><span class=\"kw-ttt\">Bleu patenté</span></td>\n            <td>Anaphylaxie peranesthésique (<span class=\"kw-ttt\">ganglion sentinelle</span>)</td>\n          </tr>\n          <tr>\n            <td><strong>Produits de contraste iodés</strong></td>\n            <td>PCI</td>\n            <td>HS non <span class=\"kw-etio\">allergique</span> (histaminolibération) — <span class=\"kw-ci\">l'allergie à l'iode n'existe pas</span> (atome non immunogène)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5>Syndromes graves à connaître (toxidermies, type IV)</h5>\n      <ul>\n        <li><strong><span class=\"kw-alerte\">DRESS</span></strong> — Drug Reaction with Eosinophilia and Systemic Symptoms — délai <span class=\"kw-chiffre\">2–6 semaines</span>, <span class=\"kw-clinique\">fièvre</span>, exanthème, hyperéosinophilie, atteinte viscérale (hépatique, rénale).</li>\n        <li><strong><span class=\"kw-alerte\">Stevens-Johnson / Lyell (NET)</span></strong> — délai <span class=\"kw-chiffre\">4–28 jours</span>, décollement cutanéo-muqueux, <span class=\"kw-def\">mortalité</span><span class=\"kw-chiffre\"> 30 %</span> pour le <span class=\"kw-alerte\">Lyell</span>.</li>\n        <li><strong><span class=\"kw-alerte\">PEAG</span></strong> — Pustulose Exanthématique Aiguë Généralisée — délai <span class=\"kw-chiffre\">1–11 jours</span>, pustules amicrobiennes.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>Réflexe pharmacovigilance</strong> — toute réaction d'HS médicamenteuse doit être <strong>déclarée au centre de pharmacovigilance</strong> 📞. Tenir une <strong>carte d'<span class=\"kw-ci\">allergie</span></strong> au patient mentionnant la molécule incriminée et <span class=\"kw-clinique\">les</span> molécules <span class=\"kw-ci\">à éviter</span> par <span class=\"kw-bio\">réaction croisée</span>.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 115 — Toxidermies · 187 — <span class=\"kw-ci\">Hypersensibilité</span>, allergies cutanées</em></p>","frequence":0},{"id":"186-5","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les éléments physiopathologiques des allergies aux venins d’hyménoptères : prévalence, mortalité","contenu":"<p>Le venin des hyménoptères contient deux familles de molécules aux mécanismes physiopathologiques distincts : des <strong>substances vaso-actives</strong> (responsables de réactions toxiques et d'HS non immunologiques) et des <strong>enzymes/protéines</strong> (responsables de réactions immuno-allergiques <span class=\"kw-bio\">IgE-médiées</span>).</p>\n\n      <h5>Composition du venin</h5>\n      <table >\n        <thead><tr><th>Composant</th><th>Nature</th><th>Effets</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Substances vaso-actives</strong></td>\n            <td>Amines biogènes <em>(histamine, sérotonine)</em>, peptides <em>(mélittine pour l'abeille)</em></td>\n            <td><span class=\"kw-clinique\">Réactions toxiques</span> dose-dépendantes (piqûres multiples), <span class=\"kw-clinique\">HS non immunologique</span> (effet pharmacologique direct sur <span class=\"kw-clinique\">les</span> mastocytes)</td>\n          </tr>\n          <tr>\n            <td><strong>Enzymes et protéines allergéniques</strong></td>\n            <td><span class=\"kw-bio\">Phospholipase A2</span> (PLA2), <span class=\"kw-bio\">hyaluronidase</span>, <span class=\"kw-bio\">antigène</span> 5</td>\n            <td><span class=\"kw-clinique\">Manifestations immuno-allergiques IgE-médiées</span> — déclenchent la dégranulation mastocytaire après sensibilisation préalable</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5>Allergènes recombinants spécifiques (intérêt diagnostique)</h5>\n      <table >\n        <thead><tr><th>Hyménoptère</th><th>Allergène majeur</th><th>Allergène complémentaire</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Abeille</strong> <em>(Apis mellifera)</em></td><td><span class=\"kw-bio\">rApi m 1</span> (phospholipase A2)</td><td>rApi m 2 (hyaluronidase), rApi m 10</td></tr>\n          <tr><td><strong>Guêpe</strong> <em>(Vespula)</em></td><td><span class=\"kw-bio\">rVes v 5</span> (<span class=\"kw-bio\">antigène</span> 5)</td><td>rVes v 1 (phospholipase A1)</td></tr>\n          <tr><td><strong>Frelon européen</strong></td><td>Communauté antigénique avec la guêpe (rVes v 5)</td><td><span class=\"kw-def\">Diagnostic différentiel</span> guêpe/frelon</td></tr>\n          <tr><td><strong>Frelon asiatique</strong> <em>(Vespa velutina)</em></td><td>Antigènes spécifiques en cours de caractérisation</td><td>Émergence récente en Europe</td></tr>\n        </tbody>\n      </table>\n\n      <h5>Mécanisme de la réaction <span class=\"kw-etio\">allergique</span> <span class=\"kw-chiffre\">IgE</span>-médiée</h5>\n      <ul>\n        <li><strong>Sensibilisation</strong> — 1ʳᵉ piqûre asymptomatique ou réaction locale → production d'<span class=\"kw-chiffre\">IgE</span> spécifiques anti-venin → fixation sur récepteurs <span class=\"kw-bio\">FcεRI</span> des mastocytes/<span class=\"kw-bio\">basophiles</span>.</li>\n        <li><strong>Réintroduction</strong> — nouvelle piqûre → <span class=\"kw-ttt\">pontage</span> des <span class=\"kw-chiffre\">IgE</span> par <span class=\"kw-clinique\">les</span> allergènes → dégranulation immédiate → libération d'<span class=\"kw-bio\">histamine</span>, <span class=\"kw-bio\">tryptase</span>, leucotriènes.</li>\n        <li><strong>Conséquences cliniques</strong> — <span class=\"kw-clinique\">choc anaphylactique</span>, <span class=\"kw-clinique\">angio-œdème</span>, <span class=\"kw-clinique\">bronchospasme</span>, <span class=\"kw-clinique\">urticaire</span>, <span class=\"kw-clinique\">hypotension</span>.</li>\n        <li><strong>Réactions croisées</strong> — fréquentes entre guêpes et frelons (communauté antigénique). Réactions croisées abeille/guêpe rares mais possibles (épitopes glycaniques type CCD = cross-reactive carbohydrate determinants).</li>\n      </ul>\n\n      <h5><span class=\"kw-def\">Classification</span> de Mueller (gradation clinique des réactions systémiques)</h5>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Grade</span></th><th>Manifestations</th><th>CAT</th></tr></thead>\n        <tbody>\n          <tr><td><strong>I</strong></td><td><span class=\"kw-clinique\">Urticaire</span> généralisée, <span class=\"kw-clinique\">prurit</span>, <span class=\"kw-clinique\">malaise</span>, anxiété</td><td>AntiH1 oral + <span class=\"kw-def\">surveillance</span></td></tr>\n          <tr><td><strong>II</strong></td><td>Angio-<span class=\"kw-clinique\">œdème</span>, oppression thoracique, <span class=\"kw-clinique\">douleurs abdominales</span>, <span class=\"kw-clinique\">nausées</span></td><td>AntiH1 + <span class=\"kw-ttt\">corticoïdes</span></td></tr>\n          <tr><td><strong>III</strong></td><td><span class=\"kw-clinique\">Dyspnée</span>, <span class=\"kw-clinique\">sibilants</span>, <span class=\"kw-clinique\">dysphagie</span>, dysphonie, <span class=\"kw-clinique\">vertiges</span></td><td><span class=\"kw-alerte\">Adrénaline IM</span> + <span class=\"kw-alerte\">hospitalisation</span> + ITA discutée</td></tr>\n          <tr><td><strong>IV</strong></td><td><span class=\"kw-alerte\">Hypotension, perte de connaissance, incontinence, arrêt cardiaque</span></td><td><span class=\"kw-alerte\">Adrénaline IM en urgence</span> + <span class=\"kw-alerte\">réanimation</span> + ITA indiquée</td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Lien <span class=\"kw-def\">physiopathologie</span>–thérapeutique</strong> — l'<span class=\"kw-ttt\">immunothérapie allergénique (ITA)</span> par voie SC est le seul traitement modifiant l'histoire naturelle. Indiquée pour <span class=\"kw-clinique\">les</span> <span class=\"kw-alerte\">réactions systémiques Mueller III–IV</span> avec mécanisme <span class=\"kw-chiffre\">IgE</span> démontré. Permet la guérison la plupart du temps.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 187 — <span class=\"kw-ci\">Hypersensibilité</span>, allergies cutanées</em></p>","frequence":0},{"id":"186-6","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître et hiérarchiser les différentes étapes du diagnostic des allergies respiratoires","contenu":"<p>Le diagnostic d'une <span class=\"kw-def\">allergie respiratoire</span> (<span class=\"kw-def\">asthme</span> <span class=\"kw-etio\">allergique</span>, rhinite, rhino-conjonctivite) repose sur trois piliers à explorer dans cet ordre strict : <strong>(1) anamnèse</strong> mettant en évidence une association exposition/symptômes, <strong>(2) tests cutanés</strong> en 1ʳᵉ intention, <strong>(3) tests biologiques (<span class=\"kw-chiffre\">IgE</span> spécifiques)</strong> en 2ⁿᵈ intention si discordance ou doute.</p>\n\n      <h5>Hiérarchie diagnostique en 4 étapes</h5>\n      <table >\n        <thead><tr><th>Étape</th><th>Objectif</th><th>Outils</th><th>Critères positifs</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>1 — Anamnèse</strong> ⭐</td>\n            <td>Association forte entre exposition à l'allergène et survenue des symptômes</td>\n            <td>Interrogatoire orienté : nature des symptômes, déclencheurs, saisonnalité, calendrier, professionnel, domicile, animaux, atopie familiale</td>\n            <td>Réaction <span class=\"kw-clinique\">aiguë &lt; 1 h</span>, non dose-dépendante, reproductible à chaque exposition</td>\n          </tr>\n          <tr>\n            <td><strong>2 — Tests cutanés</strong> <em>(<span class=\"kw-chiffre\">1ère intention</span>)</em></td>\n            <td>Objectiver une sensibilisation <span class=\"kw-chiffre\">IgE</span>-médiée</td>\n            <td><span class=\"kw-bio\">Prick-tests</span> sur extraits standardisés (pneumallergènes courants : acariens, pollens, animaux, moisissures) ± allergène natif si trophallergène associé</td>\n            <td><span class=\"kw-clinique\">Papule</span> <span class=\"kw-chiffre\">≥ 3 mm</span> versus témoin négatif, avec témoin positif (histamine) positif</td>\n          </tr>\n          <tr>\n            <td><strong>3 — Tests biologiques</strong> <em>(2ⁿᵈ intention)</em></td>\n            <td>Préciser la sensibilisation si discordance prick/clinique, prick CI, ou doute</td>\n            <td><span class=\"kw-bio\">IgE spécifiques</span> (5 allergènes respiratoires max remboursés) — Phadiatop si <span class=\"kw-def\">dépistage</span> <span class=\"kw-etio\">atopique</span></td>\n            <td>Taux exprimé en <span class=\"kw-chiffre\">kUA/L</span> (significatif <span class=\"kw-chiffre\">≥ 0,35</span> kUA/L)</td>\n          </tr>\n          <tr>\n            <td><strong>4 — Test de provocation</strong> <em>(rare)</em></td>\n            <td>Diagnostic de certitude si bilan 1ʳᵉ intention insuffisant et impact thérapeutique</td>\n            <td>Tests nasaux ou bronchiques avec allergène — exclusivement en <span class=\"kw-bio\">milieu spécialisé hospitalier</span></td>\n            <td>Reproduction des symptômes après administration de doses croissantes</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5>Manifestations cliniques évocatrices</h5>\n      <table >\n        <thead><tr><th>Organe</th><th>HS <span class=\"kw-chiffre\">IgE</span>-médiée (immédiate)</th><th>HS non IgE-médiée (retardée)</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>ORL / nasal</strong></td>\n            <td><span class=\"kw-clinique\">Rhinite</span> aiguë, <span class=\"kw-clinique\">prurit</span> nasal, éternuements, rhinorrhée claire, obstruction</td>\n            <td>—</td>\n          </tr>\n          <tr>\n            <td><strong>Oculaire</strong></td>\n            <td><span class=\"kw-clinique\">Conjonctivite</span>, <span class=\"kw-clinique\">prurit</span>, larmoiement, hyperhémie, chémosis</td>\n            <td>Kératite, <span class=\"kw-clinique\">œdème</span> des paupières</td>\n          </tr>\n          <tr>\n            <td><strong>Bronchopulmonaire</strong></td>\n            <td><span class=\"kw-clinique\">Toux</span>, <span class=\"kw-clinique\">asthme</span>, bronchospasme, <span class=\"kw-clinique\">sibilants</span></td>\n            <td>—</td>\n          </tr>\n          <tr>\n            <td><strong>Cutané</strong></td>\n            <td><span class=\"kw-clinique\">Urticaire</span>, angio-<span class=\"kw-clinique\">œdème</span></td>\n            <td><span class=\"kw-clinique\">Eczéma</span> de <span class=\"kw-def\">contact</span>, toxidermies</td>\n          </tr>\n          <tr>\n            <td><strong>Anaphylaxie</strong></td>\n            <td><span class=\"kw-alerte\">Hypotension, choc, arrêt cardiaque</span></td>\n            <td>—</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5>Critères discriminants <span class=\"kw-chiffre\">IgE</span> <span class=\"kw-bio\">vs</span> non-IgE <span class=\"kw-bio\">vs</span> non-<span class=\"kw-etio\">allergique</span></h5>\n      <ul>\n        <li><strong>HS <span class=\"kw-chiffre\">IgE</span>-médiée</strong> — symptômes <span class=\"kw-clinique\">aigus &lt; 1 h</span>, <span class=\"kw-clinique\">non dose-dépendants</span>, <span class=\"kw-clinique\">reproductibles</span> avec le même allergène.</li>\n        <li><strong>HS non <span class=\"kw-chiffre\">IgE</span>-médiée</strong> — symptômes <span class=\"kw-clinique\">retardés (heures-jours)</span>, chroniques, principalement cutanés ou digestifs, non dose-dépendants, reproductibles.</li>\n        <li><strong>HS non <span class=\"kw-etio\">allergique</span></strong> — délai variable, <span class=\"kw-clinique\">dose-dépendant</span> (seuil), <span class=\"kw-clinique\">non reproductible systématiquement</span>, souvent plusieurs substances.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>Examen à ne PAS prescrire</strong> ❌ — <span class=\"kw-bio\">IgE totales</span> sériques (totalement inutile, non remboursé). PNE sanguine, tryptase sérique de base hors <span class=\"kw-alerte\">anaphylaxie</span>, <span class=\"kw-chiffre\">IgG</span> spécifiques : <strong>aucune indication</strong> dans le diagnostic d'<span class=\"kw-ci\">allergie</span>. La <span class=\"kw-bio\">tryptase</span> est utile uniquement en aigu (<span class=\"kw-alerte\">anaphylaxie</span> peranesthésique) ou en suspicion de mastocytose.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 187 — <span class=\"kw-ci\">Hypersensibilité</span>, allergies cutanées · 188 — <span class=\"kw-def\">Asthme</span> - Rhinite</em></p>","frequence":0},{"id":"186-7","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les principaux allergènes de l’allergie alimentaire IgE-dépendante","contenu":"<p><span class=\"kw-clinique\">Les</span> principaux <span class=\"kw-def\">trophallergènes</span> <span class=\"kw-chiffre\">IgE</span>-dépendants varient selon l'âge. Chez l'enfant, le lait de vache et l'œuf dominent avant <span class=\"kw-chiffre\">1 an</span>, puis l'arachide prend la 1ʳᵉ place après <span class=\"kw-chiffre\">3 ans</span>. Chez l'adulte, ce sont les fruits à coque, les fruits frais et les crustacés.</p>\n\n      <h5>Cartographie des allergènes par âge</h5>\n      <table >\n        <thead><tr><th>Tranche d'âge</th><th>Allergènes principaux</th><th>Protéines en cause</th><th><span class=\"kw-clinique\">Évolution</span> typique</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>&lt;<span class=\"kw-chiffre\"> 6 mois</span></strong></td>\n            <td><span class=\"kw-etio\">Lait de vache</span> ⭐</td>\n            <td><span class=\"kw-bio\">Caséine</span>, <span class=\"kw-bio\">α-lactalbumine</span>, <span class=\"kw-bio\">β-lactoglobuline</span></td>\n            <td>Guérison spontanée dans <span class=\"kw-chiffre\">~80 %</span> des cas avant <span class=\"kw-chiffre\">3 ans</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-chiffre\">5–15 mois</span></strong></td>\n            <td><span class=\"kw-etio\">Œuf</span> (le plus fréquent), <span class=\"kw-etio\">arachide</span>, lait de vache, <span class=\"kw-etio\">moutarde</span>, <span class=\"kw-etio\">morue</span></td>\n            <td><span class=\"kw-bio\">Ovalbumine</span>, <span class=\"kw-bio\">ovomucoïde</span> (œuf, plus thermorésistant)</td>\n            <td>Œuf — guérison ~<span class=\"kw-chiffre\">80 %</span>. Arachide — persistance ~<span class=\"kw-chiffre\">80 %</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>&gt;<span class=\"kw-chiffre\"> 3 ans</span></strong></td>\n            <td><span class=\"kw-etio\">Arachide</span> (cacahuète) ⭐</td>\n            <td><span class=\"kw-bio\">Ara h 2</span> (<span class=\"kw-clinique\">PR</span>-2S albumines, marqueur de gravité), Ara h 1, Ara h 3</td>\n            <td>Persistance <span class=\"kw-chiffre\">~80 %</span> — allergène le plus mortel en pédiatrie</td>\n          </tr>\n          <tr>\n            <td><strong>Adulte</strong></td>\n            <td>\n              <span class=\"kw-etio\">Fruits à coque</span> (pistache, noix de cajou, noisette, noix, amande) ;\n              <span class=\"kw-etio\">Fruits frais</span> (pomme, poire, prune, pêche, abricot, kiwi) ;\n              <span class=\"kw-etio\">Crustacés</span> ;\n              <span class=\"kw-etio\">Soja</span>\n            </td>\n            <td><span class=\"kw-clinique\">PR</span>-10 (homologues de Bet v 1 du bouleau), LTP, tropomyosines (crustacés)</td>\n            <td>Persistance le plus souvent — surtout fruits à coque, poissons, crustacés</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5>Réactions <span class=\"kw-chiffre\">IgE</span>-médiées : présentation clinique</h5>\n      <ul>\n        <li><strong>Délai d'apparition</strong> — <span class=\"kw-clinique\">&lt; 1 h</span> en général (parfois quelques heures).</li>\n        <li><strong>Caractère</strong> — <span class=\"kw-clinique\">non dose-dépendant</span> (peut survenir pour une trace), <span class=\"kw-clinique\">reproductible</span> à chaque exposition.</li>\n        <li><strong>Manifestations</strong> — <span class=\"kw-clinique\">cutanées</span> (<span class=\"kw-clinique\">urticaire</span>, angio-<span class=\"kw-clinique\">œdème</span>), <span class=\"kw-clinique\">digestives</span> (<span class=\"kw-clinique\">vomissements</span>, douleurs, <span class=\"kw-clinique\">diarrhée</span>), <span class=\"kw-clinique\">respiratoires</span> (bronchospasme, rhino-conjonctivite), <span class=\"kw-alerte\">anaphylaxie</span>.</li>\n        <li><strong>Syndrome oral</strong> (pollen-aliment) — <span class=\"kw-clinique\">œdème</span> labial/lingual, <span class=\"kw-clinique\">prurit</span> buccal/pharyngé, <span class=\"kw-clinique\">érythème</span> lingual ou palatin, souvent isolé, sur <span class=\"kw-def\">terrain</span> pollinique.</li>\n      </ul>\n\n      <h5><span class=\"kw-ci\">Allergie</span> à l'arachide : focus pédagogique</h5>\n      <table >\n        <thead><tr><th>Item</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-def\">Prévalence</span></strong></td><td><span class=\"kw-chiffre\">~1 %</span> de la population générale</td></tr>\n          <tr><td><strong>Mécanisme</strong></td><td><span class=\"kw-bio\">IgE-médiée exclusivement</span></td></tr>\n          <tr><td><strong>Allergies associées</strong></td><td>Fréquemment associée à <span class=\"kw-clinique\">fruits à coque</span> (noix, pistache, cajou, noisette) ; <span class=\"kw-clinique\">rarement</span> associée aux autres légumineuses ⭐</td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Évolution</span></strong></td><td><span class=\"kw-ci\">Allergie</span> <span class=\"kw-alerte\">persistante au cours de la vie</span></td></tr>\n          <tr><td><strong>Gravité</strong></td><td>Allergène le plus fréquemment impliqué dans <span class=\"kw-clinique\">les</span> <span class=\"kw-alerte\">anaphylaxies sévères et les décès</span> 🏴‍☠️</td></tr>\n        </tbody>\n      </table>\n\n      <h5>APLV (<span class=\"kw-ci\">allergie</span> aux protéines de lait de vache) : focus</h5>\n      <table >\n        <thead><tr><th>Forme</th><th>Manifestations</th><th>Confirmation diagnostique</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-chiffre\">IgE</span>-médiée</strong></td>\n            <td>Manifestations immédiates : <span class=\"kw-clinique\">cutanées, respiratoires, digestives, anaphylactiques</span></td>\n            <td><span class=\"kw-bio\">Prick-tests</span> et/ou <span class=\"kw-bio\">dosage IgE spécifiques</span> au lait de vache ; test de provocation orale si doute</td>\n          </tr>\n          <tr>\n            <td><strong>Non <span class=\"kw-chiffre\">IgE</span>-médiée</strong></td>\n            <td>Anomalie du transit, <span class=\"kw-clinique\">RGO sévère</span>, retard pondéral, <span class=\"kw-clinique\">eczéma</span> modéré-sévère, proctocolite <span class=\"kw-etio\">hémorragique</span> (<span class=\"kw-clinique\">rectorragies</span>), SEIPA</td>\n            <td><span class=\"kw-bio\">Aucun test utile</span> — <span class=\"kw-bio\">épreuve d'éviction-réintroduction</span> (<span class=\"kw-chiffre\">2-4 semaines</span>)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5>APLV — prise en charge nutritionnelle</h5>\n      <table >\n        <thead><tr><th>Ligne</th><th>Substitut</th><th>Indication / Particularités</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>1ʳᵉ ligne</strong></td>\n            <td><span class=\"kw-ttt\">Hydrolysat poussé de protéines de lait de vache</span> (eHF — extensively hydrolysed formula)</td>\n            <td>Protéines fragmentées en peptides &lt; 1500 Da → <span class=\"kw-bio\">perte de l'antigénicité</span>. Toléré par ~<span class=\"kw-chiffre\">90 %</span> des nourrissons APLV. <span class=\"kw-ci\">Goût amer</span> (acceptation parfois difficile).</td>\n          </tr>\n          <tr>\n            <td><strong>2ⁿᵈᵉ ligne</strong></td>\n            <td><span class=\"kw-ttt\">Formule à base d'acides aminés</span> (AAF — amino acid formula)</td>\n            <td>Indiquée si <span class=\"kw-alerte\">échec ou intolérance à l'hydrolysat poussé</span>, formes sévères (<span class=\"kw-alerte\">anaphylaxie</span>, retard pondéral, SEIPA), ou doute diagnostique persistant. <span class=\"kw-bio\">Antigénicité nulle</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>Éviction stricte associée</strong></td>\n            <td>—</td>\n            <td><span class=\"kw-ci\">Pas de lait de chèvre ni de brebis</span> (réactivité croisée &gt;<span class=\"kw-chiffre\"> 90 %</span> avec le lait de vache). <span class=\"kw-ci\">Pas de jus végétaux</span> (riz, amande, soja avant <span class=\"kw-chiffre\">6 mois</span>) comme substitut nutritionnel exclusif — déséquilibre protéique et risque de carences.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-ci\">Allaitement</span> maternel</strong></td>\n            <td>À privilégier</td>\n            <td>Éviction des produits laitiers chez la mère si APLV confirmée chez le nourrisson allaité. <span class=\"kw-bio\">Supplémentation calcium + vitamine D</span> chez la mère.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>SEIPA</strong> 🔥 — Syndrome d'Entérocolite Induite par <span class=\"kw-clinique\">les</span> Protéines Alimentaires : forme aiguë spectaculaire avec <span class=\"kw-clinique\">vomissements en jet, répétés, incoercibles</span> + <span class=\"kw-clinique\">pâleur</span>, léthargie, <span class=\"kw-clinique\">déshydratation</span>, <span class=\"kw-chiffre\">1–4 h</span> après ingestion ; <span class=\"kw-bio\">diarrhée</span> possible <span class=\"kw-chiffre\">5–10 h</span> plus tard. Recours fréquent aux urgences pour réhydratation.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 187 — <span class=\"kw-ci\">Hypersensibilité</span>, allergies cutanées · 188 — <span class=\"kw-def\">Asthme</span> - Rhinite</em></p>","frequence":0},{"id":"186-8","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître l’algorithme de prise en charge diagnostique et thérapeutique de l’allergie alimentaire IgE-dépendante à l’arachide et aux fruits à coque","contenu":"<p>L'<span class=\"kw-ci\">allergie</span> à l'<span class=\"kw-def\">arachide</span> et aux <span class=\"kw-def\">fruits à coque</span> est l'allergie alimentaire la plus mortelle, persistante dans <span class=\"kw-chiffre\">~80 %</span> des cas. La prise en charge associe diagnostic strict (anamnèse + prick + <span class=\"kw-chiffre\">IgE</span> + TPO) et éviction totale + trousse d'<span class=\"kw-alerte\">urgence</span> avec <span class=\"kw-ttt\">adrénaline</span> auto-injectable.</p>\n\n      <h5>Algorithme diagnostique</h5>\n      <table >\n        <thead><tr><th>Étape</th><th>Examen</th><th>Interprétation / décision</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>1 — Anamnèse</strong></td>\n            <td>Histoire clinique d'une réaction immédiate (<span class=\"kw-clinique\">urticaire</span>, angio-<span class=\"kw-clinique\">œdème</span>, <span class=\"kw-alerte\">anaphylaxie</span>) compatible avec une réaction <span class=\"kw-chiffre\">IgE</span>-médiée à l'arachide ou aux fruits à coque</td>\n            <td>Réaction <span class=\"kw-clinique\">&lt; 1 h</span> après ingestion, <span class=\"kw-clinique\">non dose-dépendante</span>, <span class=\"kw-clinique\">reproductible</span></td>\n          </tr>\n          <tr>\n            <td><strong>2 — Prick-tests</strong></td>\n            <td><span class=\"kw-bio\">Prick-tests</span> sur extraits standardisés ou allergène natif (cacahuète crue)</td>\n            <td><span class=\"kw-clinique\">Papule</span> <span class=\"kw-chiffre\">≥ 3 mm</span> versus témoin négatif = sensibilisation ; ne préjuge pas de l'<span class=\"kw-ci\">allergie</span> clinique</td>\n          </tr>\n          <tr>\n            <td><strong>3 — <span class=\"kw-chiffre\">IgE</span> spécifiques</strong></td>\n            <td><span class=\"kw-bio\">IgE recombinantes</span> contre composants spécifiques : <span class=\"kw-bio\">Ara h 2</span> (marqueur de gravité, <span class=\"kw-alerte\">anaphylaxie</span>)</td>\n            <td>Précise la sensibilisation et le risque d'<span class=\"kw-alerte\">anaphylaxie</span> ; Ara h 2 positif → forte probabilité d'<span class=\"kw-ci\">allergie</span> vraie sévère</td>\n          </tr>\n          <tr>\n            <td><strong>4 — Test de provocation orale (TPO)</strong></td>\n            <td><span class=\"kw-bio\">Doses croissantes</span> en double aveugle contre placebo, en milieu hospitalier spécialisé</td>\n            <td>Indication en cas de <span class=\"kw-clinique\">doute persistant</span> ou pour vérifier l'acquisition d'une tolérance ; <span class=\"kw-ci\">CI absolues</span> : <span class=\"kw-ci\">grossesse</span>, β-bloquants, <span class=\"kw-def\">asthme</span> non contrôlé</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5>Algorithme thérapeutique</h5>\n      <table >\n        <thead><tr><th>Volet</th><th>Mesures</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Régime d'éviction strict</strong></td>\n            <td>\n              <strong>Éviction de tout produit contenant de l'arachide ou fruits à coque</strong><br>\n              <strong>Étiquetage :</strong> l'arachide est à <span class=\"kw-bio\">étiquetage obligatoire</span><br>\n              <strong>Mentions tolérées :</strong> « traces », « peut contenir » sont <span class=\"kw-ci\">autorisées légalement</span> ⭐ — vigilance maximale<br>\n              <strong>Huile d'arachide :</strong> également présente possiblement\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Suivi</span> spécialisé</strong></td>\n            <td>Allergologue, centre expert — <span class=\"kw-def\">réévaluation</span> par TPO en suivi pour rechercher une tolérance <span class=\"kw-etio\">acquise</span></td>\n          </tr>\n          <tr>\n            <td><strong>Trousse d'<span class=\"kw-alerte\">urgence</span></strong></td>\n            <td>\n              <span class=\"kw-ttt\">Adrénaline auto-injectable</span> (le plus souvent indiquée)<br>\n              <span class=\"kw-ttt\">Antihistaminiques H1</span> + <span class=\"kw-ttt\">corticoïdes oraux</span><br>\n              <span class=\"kw-ttt\">Bronchodilatateurs</span> (β2-mimétiques) si ATCD de bronchospasme\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Enquête extension</strong></td>\n            <td>Recherche systématique d'allergies croisées : autres <span class=\"kw-clinique\">fruits à coque</span> et <span class=\"kw-clinique\">légumineuses</span> à prévoir ⭐</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Éducation thérapeutique</span></strong></td>\n            <td>Lecture des étiquettes, identification des aliments à risque, conduite à tenir en cas de réaction, utilisation correcte du stylo d'<span class=\"kw-ttt\">adrénaline</span></td>\n          </tr>\n          <tr>\n            <td><strong>PAI</strong> <em>(enfants scolarisés)</em></td>\n            <td>Projet d'Accueil Individualisé établi à la demande des parents — protocole de soins en cas d'accident scolaire</td>\n          </tr>\n          <tr>\n            <td><strong>ITO</strong> <em>(immunothérapie orale)</em></td>\n            <td>Discutée en <span class=\"kw-bio\">centre expert</span> seulement — protocole de doses croissantes pour induire une tolérance ; n'efface pas le risque mais augmente la dose seuil</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5>Indications absolues de l'<span class=\"kw-ttt\">adrénaline</span> auto-injectable</h5>\n      <ul>\n        <li><strong>Anaphylaxie antérieure</strong> à un aliment, piqûre d'insecte, latex, induite par l'effort, ou idiopathique.</li>\n        <li><strong><span class=\"kw-ci\">Allergie</span> alimentaire + <span class=\"kw-def\">asthme</span></strong> persistant modéré à sévère non contrôlé.</li>\n        <li><strong>Mastocytose systémique</strong> chez l'adulte avec ATCD de réaction systémique.</li>\n        <li><strong><span class=\"kw-ci\">Allergie</span> aux hyménoptères chez l'enfant</strong> avec réaction systémique plus sévère que cutanéo-muqueuse.</li>\n        <li><strong><span class=\"kw-ci\">Allergie</span> aux hyménoptères chez l'adulte</strong> avec réaction systémique qui ne bénéficie pas d'une ITA.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>Discriminant clé</strong> — la <span class=\"kw-alerte\">positivité d'Ara h 2</span> (allergène recombinant) signe une <strong><span class=\"kw-ci\">allergie</span> vraie à l'arachide</strong> avec risque d'<span class=\"kw-alerte\">anaphylaxie</span>. Une simple positivité du prick à l'extrait total peut traduire une sensibilisation croisée (Ara h 8 / <span class=\"kw-clinique\">PR</span>-10) sans risque anaphylactique majeur — d'où l'intérêt du diagnostic moléculaire.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 187 — <span class=\"kw-ci\">Hypersensibilité</span>, allergies cutanées</em></p>","frequence":0},{"id":"186-9","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître l’algorithme de prise en charge diagnostique et thérapeutique de l’allergie alimentaire aux allergènes croisant avec les pneumallergènes","contenu":"<p><span class=\"kw-clinique\">Les</span> <span class=\"kw-def\">allergies croisées pollen-aliment</span> ou aéroallergène-aliment sont liées à la reconnaissance par des <span class=\"kw-chiffre\">IgE</span> spécifiques d'allergènes homologues présents dans des sources distinctes. Tableau typique : <span class=\"kw-def\">terrain</span> pollinique connu + apparition d'un <strong>syndrome oral</strong> à l'ingestion d'un fruit cru.</p>\n\n      <h5>Présentation clinique typique</h5>\n      <ul>\n        <li><strong><span class=\"kw-def\">Terrain</span></strong> — patient ayant une <span class=\"kw-clinique\">allergie pollinique</span> connue (rhinite, rhino-conjonctivite saisonnière).</li>\n        <li><strong>Facteur déclenchant</strong> — consommation d'un <span class=\"kw-clinique\">fruit cru</span> ou d'un légume cru.</li>\n        <li><strong>Manifestation</strong> — <span class=\"kw-clinique\">syndrome oral</span> : <span class=\"kw-clinique\">œdème</span> labial ou lingual, <span class=\"kw-clinique\">prurit</span> buccal ou pharyngé, <span class=\"kw-clinique\">érythème</span> labial/lingual/palatin.</li>\n        <li><strong>Sévérité</strong> — généralement bénigne (syndrome oral isolé) ; rarement systémique (sauf cas particulier des <span class=\"kw-bio\">LTP</span> thermo-résistantes).</li>\n      </ul>\n\n      <h5>Principaux croisements à connaître</h5>\n      <table >\n        <thead><tr><th>Aéroallergène source</th><th>Aliments croisants</th><th>Allergène commun</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Bouleau</span></strong> (pollen d'arbre, mars-avril)</td>\n            <td>Pomme, pêche, abricot, cerise — <em>« syndrome bouleau-pomme »</em></td>\n            <td><span class=\"kw-bio\">PR-10</span> (Bet v 1 / Mal d 1) — protéine de résistance, <span class=\"kw-bio\">thermolabile</span> (détruite par cuisson)</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Armoise, pariétaire</span></strong> (herbacées)</td>\n            <td>Céleri, pêche, noisette</td>\n            <td><span class=\"kw-bio\">LTP</span> (Lipid Transfer Protein) — <span class=\"kw-bio\">thermo-résistante</span>, risque systémique</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Latex</span></strong></td>\n            <td>Banane, fruits exotiques (avocat, kiwi, fruit de la passion) — <em>syndrome latex-fruits</em></td>\n            <td><span class=\"kw-bio\">Profilines</span>, <span class=\"kw-bio\">chitinases</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Acariens</span></strong></td>\n            <td>Crustacés, mollusques</td>\n            <td><span class=\"kw-bio\">Tropomyosines</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Chat</span></strong> (squames)</td>\n            <td>Porc, abats — <em>syndrome porc-chat</em></td>\n            <td><span class=\"kw-bio\">Albumines</span> sériques</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Cyprès</span></strong></td>\n            <td>Pêche, agrumes</td>\n            <td>—</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Plumes / déjections d'oiseaux</span></strong></td>\n            <td>Œuf — <em>syndrome œuf-oiseau</em></td>\n            <td>Sensibilisation respiratoire première, <span class=\"kw-ci\">allergie</span> alimentaire secondaire</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5>Algorithme diagnostique</h5>\n      <table >\n        <thead><tr><th>Étape</th><th>Action</th><th>Particularité</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>1 — Anamnèse</strong></td>\n            <td>Symptômes oraux à l'ingestion d'un fruit/légume <strong>cru</strong>, disparaissant à la cuisson (<span class=\"kw-clinique\">PR</span>-10 thermolabiles)</td>\n            <td>Préciser le contexte saisonnier (pic pollinique = aggravation des symptômes alimentaires)</td>\n          </tr>\n          <tr>\n            <td><strong>2 — Prick-tests</strong></td>\n            <td><span class=\"kw-bio\">Prick sur extrait commercial</span> souvent négatif (instabilité des <span class=\"kw-clinique\">PR</span>-10)<br><span class=\"kw-bio\">Prick-prick avec aliment natif</span> (frais) : <strong>plus sensible</strong></td>\n            <td>Si extrait commercial négatif mais clinique évocatrice → tester le fruit frais</td>\n          </tr>\n          <tr>\n            <td><strong>3 — <span class=\"kw-chiffre\">IgE</span> spécifiques recombinantes</strong></td>\n            <td>Bet v 1 (bouleau), Mal d 1 (pomme), Pru p 3 (pêche, LTP)</td>\n            <td>Distingue <span class=\"kw-clinique\">les</span> croisements bénins (PR-10 thermolabiles) des risques systémiques (LTP)</td>\n          </tr>\n          <tr>\n            <td><strong>4 — TPO</strong></td>\n            <td>Rarement nécessaire — réservé aux cas de doute persistant</td>\n            <td>Inutile pour <span class=\"kw-clinique\">les</span> syndromes oraux typiques bénins</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5>Prise en charge thérapeutique</h5>\n      <ul>\n        <li><strong>Éviction des fruits/légumes responsables</strong> sous forme <span class=\"kw-clinique\">crue</span> uniquement — la cuisson détruit <span class=\"kw-clinique\">les</span> PR-10 (sauf LTP qui restent actives).</li>\n        <li><strong>Pas de trousse d'<span class=\"kw-alerte\">urgence</span> systématique</strong> — réservée aux formes systémiques ou aux LTP-allergies.</li>\n        <li><strong>Antihistaminiques <span class=\"kw-chiffre\">H1</span></strong> en cas de syndrome oral modéré.</li>\n        <li><strong>Pas d'ITA spécifique</strong> pour <span class=\"kw-clinique\">les</span> allergies alimentaires croisées — l'ITA pollinique du bouleau peut parfois améliorer la tolérance alimentaire.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>Drapeau LTP</strong> ⚠️ — <span class=\"kw-clinique\">les</span> LTP (Pru p 3 de la pêche, par exemple) sont <span class=\"kw-alerte\">thermo-résistantes et résistantes à la digestion</span>, donc capables de provoquer des <span class=\"kw-alerte\">réactions systémiques sévères</span>, parfois à l'effort. Particularité méditerranéenne. À distinguer formellement des <span class=\"kw-clinique\">PR</span>-10 (bénins).\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 187 — <span class=\"kw-ci\">Hypersensibilité</span>, allergies cutanées · 188 — <span class=\"kw-def\">Asthme</span> - Rhinite</em></p>","frequence":0},{"id":"186-10","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître et hiérarchiser les différentes étapes du diagnostic des allergies aux venins d’hyménoptères","contenu":"<p>Le diagnostic d'une <span class=\"kw-def\">allergie aux venins d'hyménoptères</span> hiérarchise systématiquement : <strong>(1) anamnèse</strong> (identification de l'insecte + <span class=\"kw-def\">classification</span> de Mueller du type de réaction) → <strong>(2) tests cutanés <span class=\"kw-clinique\">IDR</span></strong> (et non prick en <span class=\"kw-chiffre\">première intention</span> pour <span class=\"kw-clinique\">les</span> venins) → <strong>(3) <span class=\"kw-chiffre\">IgE</span> spécifiques avec recombinants</strong> → <strong>(4) recherche de mastocytose</strong> si <span class=\"kw-alerte\">anaphylaxie</span>.</p>\n\n      <h5>Étapes diagnostiques hiérarchisées</h5>\n      <table >\n        <thead><tr><th>Étape</th><th>Outil</th><th>Particularités</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>1 — Anamnèse</strong></td>\n            <td>\n              <strong>Identification de l'espèce</strong> par le sujet (abeille / guêpe / frelon)<br>\n              <strong>Type de réaction :</strong> locale étendue <span class=\"kw-bio\">vs</span> systémique<br>\n              <strong><span class=\"kw-def\">Classification</span> de Mueller</strong> (<span class=\"kw-def\">grade</span> I à IV)<br>\n              <strong>Chronologie</strong> et délai d'apparition des symptômes<br>\n              <strong>ATCD</strong> de réactions antérieures et leur gravité\n            </td>\n            <td>Recherche du dard restant (typique de l'abeille) — la guêpe ne laisse pas son dard</td>\n          </tr>\n          <tr>\n            <td><strong>2 — Tests cutanés</strong></td>\n            <td>\n              <span class=\"kw-bio\">IDR à lecture immédiate</span> (et non prick en 1ʳᵉ intention pour <span class=\"kw-clinique\">les</span> venins) ⭐<br>\n              Lecture à <span class=\"kw-chiffre\">20 minutes</span><br>\n              Réalisée en <span class=\"kw-bio\">milieu spécialisé hospitalier</span>\n            </td>\n            <td>Témoin négatif (sérum physiologique) mais <span class=\"kw-ci\">pas de témoin positif</span> systématique</td>\n          </tr>\n          <tr>\n            <td><strong>3 — <span class=\"kw-chiffre\">IgE</span> spécifiques</strong></td>\n            <td>\n              <span class=\"kw-bio\">IgE contre extraits totaux</span> (Apis mellifera, Vespula)<br>\n              <span class=\"kw-bio\">IgE recombinantes</span> : rApi m 1 (abeille), rVes v 5 (guêpe)\n            </td>\n            <td>Distingue <span class=\"kw-clinique\">les</span> co-sensibilisations vraies des réactions croisées <span class=\"kw-bio\">CCD</span> (cross-reactive carbohydrate determinants)</td>\n          </tr>\n          <tr>\n            <td><strong>4 — Recherche de mastocytose</strong></td>\n            <td><span class=\"kw-bio\">Tryptase basale sérique</span> systématique après tout épisode d'<span class=\"kw-alerte\">anaphylaxie</span> aux hyménoptères</td>\n            <td>Si tryptase &gt; <span class=\"kw-chiffre\">20 ng/mL</span> → bilan de mastocytose (<span class=\"kw-bio\">biopsie</span> médullaire, mutation KIT D816V)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5><span class=\"kw-def\">Classification</span> de Mueller — guide diagnostique et thérapeutique</h5>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Grade</span></th><th>Manifestations</th><th>Décision diagnostique</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-def\">Grade</span> I</strong></td>\n            <td><span class=\"kw-clinique\">Urticaire</span> généralisée, <span class=\"kw-clinique\">prurit</span>, <span class=\"kw-clinique\">malaise</span>, anxiété</td>\n            <td>Bilan allergologique recommandé ; ITA non systématique chez l'adulte</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Grade</span> II</strong></td>\n            <td>Angio-<span class=\"kw-clinique\">œdème</span>, oppression thoracique, <span class=\"kw-clinique\">douleurs abdominales</span>, <span class=\"kw-clinique\">nausées</span></td>\n            <td>Bilan obl<span class=\"kw-chiffre\">iga</span>toire ; ITA souvent indiquée</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Grade</span> III</strong></td>\n            <td><span class=\"kw-clinique\">Dyspnée</span>, <span class=\"kw-clinique\">sibilants</span>, <span class=\"kw-clinique\">dysphagie</span>, dysphonie, <span class=\"kw-clinique\">vertiges</span></td>\n            <td><span class=\"kw-alerte\">ITA indiquée</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Grade</span> IV</strong></td>\n            <td><span class=\"kw-alerte\">Hypotension, perte de connaissance, incontinence, arrêt cardiaque</span></td>\n            <td><span class=\"kw-alerte\">ITA indiquée + dosage tryptase basale (recherche mastocytose)</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5>Tests cellulaires (cas particuliers, recherche)</h5>\n      <ul>\n        <li><strong>Test d'activation des <span class=\"kw-bio\">basophiles</span> (TAB)</strong> — réservé aux cas de discordance entre clinique évocatrice et tests négatifs ; non disponible en routine.</li>\n        <li><strong>Indications</strong> — bilan complexe en centre expert pour discordance prick/<span class=\"kw-clinique\">IDR</span>/<span class=\"kw-chiffre\">IgE</span>.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>Spécificité venins <span class=\"kw-bio\">vs</span> autres allergènes</strong> — l'<strong><span class=\"kw-clinique\">IDR</span> à lecture immédiate</strong> est la méthode de référence pour <span class=\"kw-clinique\">les</span> venins d'hyménoptères et les <span class=\"kw-ttt\">médicaments injectables</span>, alors que le <strong>prick-test</strong> est utilisé en 1ʳᵉ intention pour les pneumallergènes et les trophallergènes.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 187 — <span class=\"kw-ci\">Hypersensibilité</span>, allergies cutanées</em></p>","frequence":0},{"id":"186-11","rang":"A","rubrique":"Étiologies","titre":"Connaître le rôle de l’environnement extérieur, domestique et professionnel dans l’allergie","contenu":"<p><span class=\"kw-clinique\">Les</span> <span class=\"kw-def\">allergènes</span> sont classés selon leur voie d'exposition et leur localisation : <strong>pneumallergènes</strong> (aéroportés, inhalés), <strong>trophallergènes</strong> (alimentaires), <strong>allergènes professionnels</strong>, et autres (venins, médicaments, latex). La <span class=\"kw-bio\">prévalence des allergies respiratoires a doublé</span> en <span class=\"kw-chiffre\">20 ans</span> (rôle des modifications environnementales).</p>\n\n      <h5>Pneumallergènes domestiques (perannuels)</h5>\n      <table >\n        <thead><tr><th>Allergène</th><th>Localisation typique</th><th>Conditions de prolifération</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Acariens</span></strong> ⭐ <em>(Dermatophagoides pteronyssinus, D. farinae)</em></td>\n            <td>Poussières de maison — literie ++, tapis, moquettes, peluches, canapés</td>\n            <td>Température <span class=\"kw-chiffre\">20–25 °C</span> + humidité — ubiquitaires en climat tempéré</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Phanères d'animaux</span></strong></td>\n            <td>Chien, chat, rongeurs (NAC) — squames, salive, urine</td>\n            <td>Allergènes de chat <span class=\"kw-alerte\">persistent &gt; plusieurs mois</span> après le départ de l'animal</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Blattes</span></strong> <em>(cafards)</em></td>\n            <td>Cuisines, salles de bain, conditions d'hygiène défavorables</td>\n            <td>Allergène majeur des allergies respiratoires en milieu urbain défavorisé</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Moisissures intérieures</span></strong></td>\n            <td>Pièces humides — salle de bain, cuisine, caves</td>\n            <td><em>Aspergillus, Penicillium</em></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Alternaria</span></strong></td>\n            <td>Moisissure d'<strong>extérieur</strong> (compost, feuilles mortes)</td>\n            <td>Marqueur de gravité asthmatique chez l'enfant (<span class=\"kw-def\"><span class=\"kw-def\">asthme</span> aigu grave</span>)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5>Pneumallergènes extérieurs (saisonniers)</h5>\n      <table >\n        <thead><tr><th>Famille</th><th>Pollens</th><th>Période d'émission</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Arbres</strong></td>\n            <td>Bétulacées (<span class=\"kw-etio\">bouleau</span>, aulne, charme, noisetier), <span class=\"kw-etio\">cyprès</span> (sud de la France)</td>\n            <td>Début de printemps — <span class=\"kw-chiffre\">mars-avril</span></td>\n          </tr>\n          <tr>\n            <td><strong>Graminées</strong></td>\n            <td><span class=\"kw-etio\">Graminées</span> (<span class=\"kw-clinique\">les</span> plus ubiquitaires)</td>\n            <td>Fin du printemps / début été — <span class=\"kw-chiffre\">mai-juillet</span></td>\n          </tr>\n          <tr>\n            <td><strong>Herbacées</strong></td>\n            <td><span class=\"kw-etio\">Armoise</span>, <span class=\"kw-etio\">ambroisie</span></td>\n            <td>Printemps et été — <span class=\"kw-chiffre\">avril-septembre</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5>Allergènes professionnels (<span class=\"kw-def\">asthme</span> professionnel)</h5>\n      <table >\n        <thead><tr><th>Métier</th><th>Allergène</th><th>Tableau de maladie professionnelle</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Boulanger / pâtissier</strong></td><td>Farines de céréales, enzymes (α-amylases)</td><td>RG 66 (<span class=\"kw-def\">asthme</span>), RG 66 bis</td></tr>\n          <tr><td><strong>Personnel de santé</strong></td><td><span class=\"kw-etio\">Latex</span>, glutaraldéhyde, désinfectants</td><td>RG 65, RG 95</td></tr>\n          <tr><td><strong>Coiffeur</strong></td><td>Persulfates, paraphénylènediamine</td><td>RG 66</td></tr>\n          <tr><td><strong>Peintres / industrie auto</strong></td><td><span class=\"kw-etio\">Isocyanates</span> (TDI, MDI, HDI)</td><td>RG 62</td></tr>\n          <tr><td><strong>Travailleurs du bois</strong></td><td>Poussières de bois (chêne, hêtre, exotiques)</td><td>RG 47</td></tr>\n          <tr><td><strong>Agriculteurs / éleveurs</strong></td><td>Foin moisi (actinomycètes), protéines aviaires</td><td>RA 45, RA 45 bis</td></tr>\n        </tbody>\n      </table>\n\n      <h5>Autres allergènes</h5>\n      <table >\n        <thead><tr><th>Famille</th><th>Allergènes</th><th>Particularités</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Venins d'hyménoptères</strong></td>\n            <td><span class=\"kw-etio\">Abeille, guêpe, frelon, bourdon</span></td>\n            <td>Plus fréquentes chez l'adulte ; ITA si <span class=\"kw-alerte\">anaphylaxie</span></td>\n          </tr>\n          <tr>\n            <td><strong>Médicaments</strong></td>\n            <td><span class=\"kw-ttt\">β-lactamines</span>, <span class=\"kw-ttt\">AINS</span>, <span class=\"kw-ttt\">curares</span>, <span class=\"kw-ttt\">bleu patenté</span></td>\n            <td>Rares chez l'adulte, encore plus rares chez l'enfant</td>\n          </tr>\n          <tr>\n            <td><strong>Latex</strong></td>\n            <td>Hévéine, Hev b 1-13</td>\n            <td>Moins fréquent depuis l'abandon dans le matériel médical ; syndrome latex-fruits exotiques</td>\n          </tr>\n          <tr>\n            <td><strong>Allergènes de <span class=\"kw-def\">contact</span></strong></td>\n            <td>Nickel, parfums, conservateurs cosmétiques, chromates</td>\n            <td>Rares chez l'enfant, surtout milieu professionnel — <span class=\"kw-clinique\">eczéma</span> de <span class=\"kw-def\">contact</span> (type IV)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5>Facteurs environnementaux modulant le risque <span class=\"kw-etio\">allergique</span></h5>\n      <ul>\n        <li><strong>Modification des habitudes alimentaires</strong> — diversification précoce, occidentalisation.</li>\n        <li><strong><span class=\"kw-etio\">Tabagisme</span></strong> — passif (pré- et post-natal) → augmentation du risque <span class=\"kw-etio\">atopique</span>.</li>\n        <li><strong>Pollution atmosphérique</strong> — particules fines, ozone, NO₂ → potentialisation de l'effet des pollens.</li>\n        <li><strong>Théorie hygiéniste</strong> — baisse des contacts <span class=\"kw-etio\">infectieux</span> dans l'enfance corrélée à l'augmentation des maladies allergiques et auto-immunes. La <span class=\"kw-bio\">baisse de la biodiversité microbienne</span> est aujourd'hui privilégiée comme mécanisme principal.</li>\n        <li><strong>Facteurs protecteurs</strong> — enfants <span class=\"kw-clinique\">les</span> plus jeunes d'une fratrie, vie en crèche (contage <span class=\"kw-etio\">infectieux</span> précoce), milieu rural avec endotoxines bactériennes (« effet ferme »).</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>Conseiller Médical en Environnement Intérieur (CMEI)</strong> — peut visiter le domicile pour diagnostiquer la <span class=\"kw-bio\">charge allergénique</span> (mesure des Der p 1/Der f 1 pour <span class=\"kw-clinique\">les</span> acariens, Fel d 1 pour le chat). Outil pédagogique majeur pour l'<span class=\"kw-def\">éducation thérapeutique</span> et l'<span class=\"kw-bio\">éviction allergénique</span>.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 187 — <span class=\"kw-ci\">Hypersensibilité</span>, allergies cutanées · 188 — <span class=\"kw-def\">Asthme</span> - Rhinite · 115 — Toxidermies</em></p>","frequence":4},{"id":"186-12","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître l’indication de la réalisation d’un test de dépistage IgE multiallergénique (aéroallergènes et trophallergènes)","contenu":"<p><span class=\"kw-clinique\">Les</span> <span class=\"kw-def\">tests multi-allergéniques de dépistage</span> détectent simultanément des <span class=\"kw-chiffre\">IgE</span> spécifiques contre un panel d'allergènes le plus souvent rencontrés en <span class=\"kw-ci\">allergie</span> de type immédiat. Réponse <strong>qualitative</strong> (positif/négatif). Indiqués lorsque les tests cutanés ne sont pas réalisables ou en <span class=\"kw-def\">dépistage</span> d'une atopie chez un sujet polysymptomatique.</p>\n\n      <h5>Indications principales</h5>\n      <table >\n        <thead><tr><th>Test</th><th>Panel</th><th>Indication</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Phadiatop</strong></td>\n            <td><span class=\"kw-bio\">Aéroallergènes</span> <span class=\"kw-clinique\">les</span> plus fréquents <em>(acariens, pollens d'arbres et de graminées, chat, chien, moisissures, blattes)</em></td>\n            <td><span class=\"kw-def\">Dépistage</span> d'une <span class=\"kw-clinique\">atopie respiratoire</span> ; sensibilité &gt;<span class=\"kw-chiffre\"> 90 %</span></td>\n          </tr>\n          <tr>\n            <td><strong>Trophatop</strong></td>\n            <td><span class=\"kw-bio\">Trophallergènes</span> <span class=\"kw-clinique\">les</span> plus fréquents <em>(lait, œuf, arachide, soja, blé, poissons, crustacés)</em></td>\n            <td><span class=\"kw-def\">Dépistage</span> d'une <span class=\"kw-clinique\">atopie alimentaire</span> chez l'enfant</td>\n          </tr>\n          <tr>\n            <td><strong>Phadiatop Infant</strong></td>\n            <td><span class=\"kw-bio\">Aéroallergènes + trophallergènes</span> regroupés en un test unique</td>\n            <td><span class=\"kw-def\">Dépistage</span> chez le <span class=\"kw-clinique\">nourrisson et le jeune enfant</span> où le prick est limité ou si <span class=\"kw-clinique\">eczéma</span> sévère diffus</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5>Quand prescrire un test multi-allergénique ?</h5>\n      <ul>\n        <li><strong>Tests cutanés <span class=\"kw-ci\">contre-indiqués</span> ou impossibles</strong> :\n          <ul>\n            <li><span class=\"kw-ci\">Eczéma diffus</span> ou <span class=\"kw-ci\">dermographisme</span></li>\n            <li>Prise d'<span class=\"kw-ttt\">antihistaminiques</span> non sevrables</li>\n            <li>Prise d'<span class=\"kw-ttt\">antidépresseurs tricycliques</span> non interruptibles</li>\n            <li>Patient peu coopérant (jeune enfant, troubles cognitifs)</li>\n          </ul>\n        </li>\n        <li><strong>Doute diagnostique chez un patient polysymptomatique</strong> — orientation rapide vers une étiologie <span class=\"kw-etio\">atopique</span>.</li>\n        <li><strong>Sujet asthmatique sans cause évidente</strong> — <span class=\"kw-def\">dépistage</span> d'une atopie associée.</li>\n        <li><strong>Pédiatrie</strong> — quand le prick est techniquement limité avant l'âge de <span class=\"kw-chiffre\">3 mois</span> ou si <span class=\"kw-clinique\">eczéma</span> sévère.</li>\n      </ul>\n\n      <h5>Limites et interprétation</h5>\n      <table >\n        <thead><tr><th>Item</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Résultat positif</strong></td>\n            <td>Sensibilisation à au moins un des allergènes du panel — <span class=\"kw-bio\">recherche dans un 2ⁿᵈ temps</span> d'<span class=\"kw-chiffre\">IgE</span> spécifiques contre <span class=\"kw-clinique\">les</span> composants individuels pour identifier le ou les allergènes responsables</td>\n          </tr>\n          <tr>\n            <td><strong>Résultat négatif</strong></td>\n            <td>Rend une atopie peu probable, mais <span class=\"kw-ci\">n'exclut pas formellement</span> une <span class=\"kw-ci\">allergie</span> à un allergène non couvert par le panel</td>\n          </tr>\n          <tr>\n            <td><strong>Pas d'utilité</strong></td>\n            <td>Si tests cutanés possibles et clinique évocatrice ciblée — préférer <span class=\"kw-bio\">prick + IgE spécifiques</span> ciblées</td>\n          </tr>\n          <tr>\n            <td><strong>Remboursement</strong></td>\n            <td>Phadiatop / Trophatop / Phadiatop Infant remboursés ; <span class=\"kw-chiffre\">IgE</span> spécifiques limitées à 5 allergènes par catégorie remboursés</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5>Examens à NE PAS prescrire</h5>\n      <ul>\n        <li><strong><span class=\"kw-bio\">IgE totales sériques</span></strong> ❌ — <span class=\"kw-ci\">totalement inutile</span>, non spécifique, non remboursé.</li>\n        <li><strong><span class=\"kw-bio\">Polynucléaires</span> <span class=\"kw-bio\">éosinophiles</span> sanguins</strong> — non recommandés pour le diagnostic d'<span class=\"kw-ci\">allergie</span>.</li>\n        <li><strong>Tryptase sérique basale</strong> — réservée à la suspicion de mastocytose, pas au diagnostic d'<span class=\"kw-ci\">allergie</span> courante.</li>\n        <li><strong><span class=\"kw-chiffre\">IgG</span> spécifiques</strong> ❌ — <span class=\"kw-ci\">aucune indication</span> diagnostique en <span class=\"kw-ci\">allergie</span>.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>Stratégie diagnostique optimale</strong> — le test multi-allergénique est un <strong>outil de débrouillage</strong>. Sa positivité oriente vers le bilan ciblé (<span class=\"kw-chiffre\">IgE</span> spécifiques contre <span class=\"kw-clinique\">les</span> composants individuels du panel). Sa négativité chez un patient symptomatique avec exposition douteuse ne dispense pas d'un avis spécialisé.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 187 — <span class=\"kw-ci\">Hypersensibilité</span>, allergies cutanées · 188 — <span class=\"kw-def\">Asthme</span> - Rhinite</em></p>","frequence":0},{"id":"186-13","rang":"B","rubrique":"Prise en charge","titre":"Connaître les modalités de réalisation et de prescription des tests cutanés en allergologie","contenu":"<p><span class=\"kw-clinique\">Les</span> <span class=\"kw-def\">tests cutanés</span> sont la pierre angulaire du diagnostic allergologique. Trois techniques à maîtriser : <strong>prick-tests</strong> (HS immédiate <span class=\"kw-chiffre\">IgE</span>), <strong><span class=\"kw-clinique\">IDR</span></strong> (HS immédiate ciblée + HS retardée médicamenteuse), <strong>patch-tests</strong> (HS retardée type IV, <span class=\"kw-clinique\">eczéma</span> de <span class=\"kw-def\">contact</span>). Témoins positif (histamine) et négatif (sérum physiologique) obl<span class=\"kw-chiffre\">iga</span>toires.</p>\n\n      <h5>Comparaison des 3 techniques</h5>\n      <table >\n        <thead><tr><th>Critère</th><th>Prick-test</th><th><span class=\"kw-clinique\">IDR</span></th><th>Patch-test</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Indication</strong></td>\n            <td><span class=\"kw-clinique\">HS immédiate IgE-médiée</span> (pneumallergènes, trophallergènes) <em>en 1ʳᵉ intention</em></td>\n            <td>\n              <strong><span class=\"kw-clinique\">IDR</span> immédiate :</strong> <span class=\"kw-ttt\">médicaments injectables</span>, <span class=\"kw-clinique\">venins d'hyménoptères</span><br>\n              <strong>IDR retardée :</strong> <span class=\"kw-ttt\">toxidermies médicamenteuses</span>\n            </td>\n            <td><span class=\"kw-clinique\">HS retardée type IV</span> — <span class=\"kw-clinique\">eczéma</span> de <span class=\"kw-def\">contact</span> (cosmétiques, métaux), toxidermies</td>\n          </tr>\n          <tr>\n            <td><strong>Technique</strong></td>\n            <td>Dépôt d'extrait + lancette → micropuncture épidermique</td>\n            <td>Injection intradermique (aiguille 45°,<span class=\"kw-chiffre\"> 0,02-0,05 mL</span>)</td>\n            <td>Application sous occlusion sur le dos pendant <span class=\"kw-chiffre\">24-48 h</span></td>\n          </tr>\n          <tr>\n            <td><strong>Profondeur</strong></td>\n            <td>Épiderme superficiel</td>\n            <td>Derme superficiel</td>\n            <td>Pas d'effraction cutanée</td>\n          </tr>\n          <tr>\n            <td><strong>Lecture</strong></td>\n            <td><span class=\"kw-chiffre\">15 min</span></td>\n            <td><span class=\"kw-clinique\">IDR</span> immédiate : <span class=\"kw-chiffre\">20 min</span><br>IDR retardée : <span class=\"kw-chiffre\">24-48 h</span></td>\n            <td><span class=\"kw-chiffre\">48 h</span> (1ʳᵉ) puis <span class=\"kw-chiffre\">J3-J4</span> (2ⁿᵈ) ± <span class=\"kw-chiffre\">J7</span> (3ᵉ)</td>\n          </tr>\n          <tr>\n            <td><strong>Positivité</strong></td>\n            <td><span class=\"kw-clinique\">Papule</span> <span class=\"kw-chiffre\">≥ 3 mm</span> versus témoin négatif</td>\n            <td><span class=\"kw-clinique\">Papule</span> entourée d'érythème — <span class=\"kw-clinique\">diamètre</span> selon protocole</td>\n            <td>\n              <strong>+ :</strong> <span class=\"kw-clinique\">érythème</span> + papule/<span class=\"kw-ttt\">infiltration</span> (souvent irritatif)<br>\n              <strong>++ :</strong> + vésicules (souvent <span class=\"kw-etio\">allergique</span>)<br>\n              <strong>+++ :</strong> + vésiculo-bulles (presque toujours allergique)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Témoins</strong></td>\n            <td><span class=\"kw-bio\">Positif</span> (histamine ou <span class=\"kw-ttt\">codéine</span>) + <span class=\"kw-bio\">négatif</span> (sérum physiologique)</td>\n            <td>Témoin négatif (sérum physiologique) — <span class=\"kw-ci\">pas de témoin positif systématique</span></td>\n            <td>Témoin négatif (vaseline)</td>\n          </tr>\n          <tr>\n            <td><strong>Lieu</strong></td>\n            <td>Face antérieure avant-bras ou tiers supérieur du dos</td>\n            <td>Avant-bras ou dos, en milieu médicalisé</td>\n            <td>Dos, en milieu spécialisé</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5>Méthodologie détaillée des prick-tests</h5>\n      <ol>\n        <li><strong>Préparation du patient</strong> — <span class=\"kw-ci\">arrêt des antihistaminiques 7 jours avant</span> ⚠️ ; arrêt des <span class=\"kw-ci\">dermocorticoïdes 7 jours avant</span> sur la zone testée ; vérifier la peau saine.</li>\n        <li><strong>Dépôt</strong> — gouttes d'extrait allergénique pharmaceutique (pneumallergènes) ou aliment natif (trophallergènes) + témoin positif (histamine) + témoin négatif (sérum physiologique, <span class=\"kw-ci\">jamais d'eau</span>).</li>\n        <li><strong>Effraction</strong> — lancette stérile traverse la goutte → micropuncture épidermique (l'allergène pénètre la couche superficielle).</li>\n        <li><strong>Lecture à <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>15</span> min</span>utes</strong> — mesure du <span class=\"kw-bio\">plus grand diamètre de la papule</span> (sans tenir compte de l'<span class=\"kw-clinique\">érythème</span> ❌).</li>\n        <li><strong><span class=\"kw-def\">Surveillance</span></strong> — <span class=\"kw-chiffre\">≥ 30 min</span> systématique après le début des tests (risque de réaction anaphylactique exceptionnelle).</li>\n      </ol>\n\n      <h5>Faux négatifs et faux positifs</h5>\n      <table >\n        <thead><tr><th>Type</th><th>Causes</th><th>Précautions</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Faux négatifs</strong></td>\n            <td>\n              <span class=\"kw-ttt\">Antihistaminiques</span> non arrêtés (témoin positif devient négatif)<br>\n              <span class=\"kw-ttt\">Dermocorticoïdes</span> sur la zone<br>\n              Extraits commerciaux dégradés (<span class=\"kw-clinique\">PR</span>-10 thermolabiles)\n            </td>\n            <td>Vérifier la <strong>positivité du témoin positif</strong> (histamine) — sans elle, test ininterprétable</td>\n          </tr>\n          <tr>\n            <td><strong>Faux positifs</strong></td>\n            <td>\n              <span class=\"kw-clinique\">Dermographisme</span> (témoin négatif devient positif)<br>\n              <span class=\"kw-bio\">Antigène</span> puissant histaminolibérateur (<span class=\"kw-ttt\">codéine</span>, <span class=\"kw-ttt\">opiacés</span>)\n            </td>\n            <td>Vérifier la <strong>négativité du témoin négatif</strong> ; ne pas tester si dermographisme connu</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5><span class=\"kw-ci\">Contre-indications</span> et précautions</h5>\n      <ul>\n        <li><span class=\"kw-ci\">Dermographisme</span> sévère — <span class=\"kw-ci\">contre-indication</span> formelle aux pricks (faux positifs garantis).</li>\n        <li><span class=\"kw-ci\">Antihistaminiques</span> non sevrables — préférer <span class=\"kw-clinique\">les</span> tests biologiques (<span class=\"kw-chiffre\">IgE</span> multiallergéniques).</li>\n        <li><span class=\"kw-ci\">Eczéma diffus</span> sur <span class=\"kw-clinique\">les</span> zones testables — préférer les tests biologiques.</li>\n        <li><span class=\"kw-ci\">Antécédent d'anaphylaxie sévère récent</span> — discussion individualisée du rapport bénéfice/risque.</li>\n        <li><strong>Patch-tests spécifiques</strong> — réalisés à distance (<span class=\"kw-chiffre\">1 mois</span>) de la <span class=\"kw-clinique\">poussée</span> d'<span class=\"kw-clinique\">eczéma</span> ; <span class=\"kw-ci\">CI aux toxidermies graves</span> hors centre expert ; <span class=\"kw-ci\">CI sous corticoïdes ou immunosuppresseurs</span>.</li>\n      </ul>\n\n      <h5>Effets indésirables</h5>\n      <ul>\n        <li><strong>Bénins fréquents</strong> — réaction locale étendue (extension de la <span class=\"kw-clinique\">papule</span>), <span class=\"kw-clinique\">urticaire</span> généralisée, <span class=\"kw-clinique\">prurit</span>.</li>\n        <li><strong>Réactions syndromiques</strong> — rhinite, <span class=\"kw-def\">asthme</span> déclenchés par le test (rares).</li>\n        <li><strong>Anaphylaxie</strong> — <span class=\"kw-alerte\">exceptionnelle</span> mais justifie la <span class=\"kw-def\">surveillance</span> <span class=\"kw-chiffre\">≥ 30 min</span> en milieu médicalisé et la disponibilité de l'<span class=\"kw-ttt\">adrénaline</span>.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>Discriminant prick <span class=\"kw-bio\">vs</span> patch</strong> ⚠️ — le <strong>prick-test</strong> teste l'<span class=\"kw-bio\">HS immédiate IgE-médiée</span> (<span class=\"kw-chiffre\">15 min</span>) ; le <strong>patch-test</strong> teste l'<span class=\"kw-bio\">HS retardée type IV</span> (<span class=\"kw-chiffre\">48-96 h</span>). <span class=\"kw-clinique\">Confusion</span> fréquente en QCM. Patch-tests <span class=\"kw-ci\">non recommandés pour les allergies alimentaires retardées</span>.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 115 — Toxidermies · 187 — <span class=\"kw-ci\">Hypersensibilité</span>, allergies cutanées</em></p>","frequence":4},{"id":"186-14","rang":"A","rubrique":"Suivi et/ou pronostic","titre":"Connaître les principes de l’éducation thérapeutique dans l’allergie alimentaire (PAI, indication de l’adrénaline auto-injectable...)","contenu":"<p>L'<span class=\"kw-def\">éducation thérapeutique</span> (<span class=\"kw-def\">ETP</span>) dans l'<span class=\"kw-ci\">allergie</span> alimentaire vise à <strong>prévenir l'exposition accidentelle</strong> (éviction, lecture d'étiquettes) et à <strong>savoir réagir en <span class=\"kw-alerte\">urgence</span></strong> (plan d'action, trousse, <span class=\"kw-ttt\">adrénaline</span> auto-injectable). Le <span class=\"kw-bio\">Projet d'Accueil Individualisé (PAI)</span> est le pivot scolaire chez l'enfant.</p>\n\n      <h5>Composants de l'<span class=\"kw-def\">ETP</span> <span class=\"kw-ci\">allergie</span> alimentaire</h5>\n      <table >\n        <thead><tr><th>Volet</th><th>Mesures</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Régime d'éviction</strong></td>\n            <td>\n              Identification précise des aliments et des produits dérivés contenant l'allergène<br>\n              <strong>Lecture des étiquettes</strong> — apprentissage de la réglementation européenne sur <span class=\"kw-clinique\">les</span> 14 allergènes à étiquetage obl<span class=\"kw-chiffre\">iga</span>toire<br>\n              Mentions à risque : <em>« traces »</em>, <em>« peut contenir »</em>, <em>« fabriqué dans un atelier utilisant... »</em>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Trousse d'<span class=\"kw-alerte\">urgence</span></strong></td>\n            <td>\n              <span class=\"kw-ttt\">Adrénaline auto-injectable</span> (si histoire ou risque d'<span class=\"kw-alerte\">anaphylaxie</span>)<br>\n              <span class=\"kw-ttt\">Antihistaminiques H1</span> oraux<br>\n              <span class=\"kw-ttt\">Corticoïdes oraux</span><br>\n              <span class=\"kw-ttt\">Bronchodilatateurs β2-mimétiques</span> si ATCD de bronchospasme\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Plan d'action en <span class=\"kw-alerte\">urgence</span></strong></td>\n            <td>\n              Document écrit personnalisé indiquant la conduite à tenir selon <span class=\"kw-clinique\">les</span> symptômes :\n              <strong>légers</strong> (<span class=\"kw-clinique\">urticaire</span> isolée → antiH1) ;\n              <strong>modérés</strong> (digestif/respiratoire → antiH1 + CTC ± β2) ;\n              <strong>sévères / <span class=\"kw-alerte\">anaphylaxie</span></strong> (→ <span class=\"kw-alerte\">adrénaline IM</span> + appel 15 + position allongée)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>PAI</strong> <em>(Projet d'Accueil Individualisé)</em></td>\n            <td>\n              Chez l'<span class=\"kw-clinique\">enfant scolarisé</span>, établi à la demande des parents<br>\n              <span class=\"kw-bio\">Dérogation au secret médical</span> permettant d'établir un protocole de soins en cas de réaction accidentelle<br>\n              Définit <span class=\"kw-clinique\">les</span> aliments <span class=\"kw-ci\">à éviter</span> à la cantine + la trousse d'<span class=\"kw-alerte\">urgence</span> à disposition + le protocole d'injection d'<span class=\"kw-ttt\">adrénaline</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Carte d'<span class=\"kw-etio\">allergique</span></strong></td>\n            <td>Carte d'identité de l'<span class=\"kw-etio\">allergique</span> mentionnant l'allergène, <span class=\"kw-clinique\">les</span> manifestations antérieures, les médicaments <span class=\"kw-ci\">à éviter</span> et la conduite à tenir</td>\n          </tr>\n          <tr>\n            <td><strong>Pharmacovigilance</strong></td>\n            <td><span class=\"kw-bio\">Déclaration obligatoire</span> au centre de pharmacovigilance pour toute <span class=\"kw-ci\">allergie</span> médicamenteuse 📞</td>\n          </tr>\n          <tr>\n            <td><strong>β-bloquants</strong></td>\n            <td>Si un patient sous <span class=\"kw-ttt\">β-bloquant</span> a présenté une réaction anaphylactique → <span class=\"kw-ci\">remplacer par un produit d'une autre classe</span> en concertation avec le cardiologue (β-bloquant bloque l'effet de l'<span class=\"kw-ttt\">adrénaline</span> en <span class=\"kw-alerte\">urgence</span>)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5>Indications absolues de la trousse d'<span class=\"kw-alerte\">urgence</span> avec <span class=\"kw-ttt\">adrénaline</span> AI</h5>\n      <ul>\n        <li><strong>Anaphylaxie antérieure</strong> à un <span class=\"kw-etio\">aliment</span>, <span class=\"kw-etio\">piqûre d'insecte</span>, <span class=\"kw-etio\">latex</span>, induite par l'<span class=\"kw-etio\">effort</span> physique, ou <span class=\"kw-etio\">idiopathique</span>.</li>\n        <li><strong><span class=\"kw-ci\">Allergie</span> alimentaire + <span class=\"kw-def\">asthme</span></strong> persistant modéré à sévère <span class=\"kw-alerte\">non contrôlé</span> chez un même individu.</li>\n        <li><strong>Mastocytose systémique</strong> :\n          <ul>\n            <li>Adulte avec ATCD de réaction systémique</li>\n            <li>Enfant si atteinte cutanée &gt;<span class=\"kw-chiffre\"> 50 %</span> surface corporelle, tryptasémie basale &gt; <span class=\"kw-chiffre\">20 ng/mL</span>, ou bulles dans <span class=\"kw-clinique\">les</span> 3 premières années de vie</li>\n          </ul>\n        </li>\n        <li><strong><span class=\"kw-ci\">Allergie</span> aux hyménoptères chez l'enfant</strong> responsable d'une réaction systémique plus sévère que cutanéo-muqueuse.</li>\n        <li><strong><span class=\"kw-ci\">Allergie</span> aux hyménoptères chez l'adulte</strong> responsable d'une réaction systémique <span class=\"kw-bio\">ne bénéficiant pas d'une ITA</span>.</li>\n      </ul>\n\n      <h5>Indications relatives de l'<span class=\"kw-ttt\">adrénaline</span> AI</h5>\n      <ul>\n        <li>Réaction légère/modérée à une petite quantité d'aliment (inhalation, <span class=\"kw-def\">contact</span> cutané avec allergènes alimentaires).</li>\n        <li>Réaction légère/modérée à l'arachide, fruits à coque, laits de chèvre/brebis.</li>\n        <li><span class=\"kw-ci\">Allergie</span> alimentaire légère à modérée chez l'adolescent ou <span class=\"kw-clinique\">les</span> jeunes adultes (autonomie en construction).</li>\n        <li>Domicile <span class=\"kw-bio\">éloigné des structures de soins</span> avec ATCD de réaction légère à modérée à aliment, piqûre d'insecte, latex, pneumallergène.</li>\n        <li>Immunothérapie orale (ITO) pour <span class=\"kw-ci\">allergie</span> alimentaire en cours.</li>\n        <li>Réaction systémique aux venins d'hyménoptères + maladie cardiovasculaire associée.</li>\n      </ul>\n\n      <h5><span class=\"kw-def\">Classification</span> de Ring &amp; Messmer (sévérité <span class=\"kw-alerte\">anaphylaxie</span>)</h5>\n      <p>La gradation <strong>Ring &amp; Messmer</strong> stratifie la sévérité de la réaction anaphylactique et conditionne l'indication formelle d'<span class=\"kw-ttt\">adrénaline</span> (<span class=\"kw-alerte\">Grade II et plus</span>).</p>\n      <table >\n        <thead><tr><th><span class=\"kw-def\">Grade</span></th><th>Manifestations cliniques</th><th>Conduite à tenir</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-def\">Grade</span> I</strong></td>\n            <td><span class=\"kw-clinique\">Cutanéo-muqueux isolés</span> — <span class=\"kw-clinique\">érythème</span>, <span class=\"kw-clinique\">urticaire</span>, <span class=\"kw-clinique\">prurit</span>, angio-<span class=\"kw-clinique\">œdème</span> localisé sans signe muqueux pharyngé</td>\n            <td><span class=\"kw-ttt\">Antihistaminique H1</span> ± <span class=\"kw-ttt\">corticoïdes</span> ; <span class=\"kw-def\">surveillance</span> ; <span class=\"kw-ci\">adrénaline non indiquée</span></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Grade</span> II</strong></td>\n            <td>Atteinte multiviscérale modérée : <span class=\"kw-clinique\">hypotension modérée, tachycardie, dyspnée, toux, troubles digestifs</span></td>\n            <td><span class=\"kw-alerte\">Adrénaline IM</span> + remplissage + appel 15</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Grade</span> III</strong></td>\n            <td>Atteinte multiviscérale sévère menaçant la vie : <span class=\"kw-alerte\">collapsus, tachycardie/bradycardie, troubles du rythme, bronchospasme sévère</span></td>\n            <td><span class=\"kw-alerte\">Adrénaline IM</span> ± IV titrée + remplissage massif + O2 + appel 15</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Grade</span> IV</strong></td>\n            <td><span class=\"kw-alerte\">Arrêt cardio-respiratoire</span></td>\n            <td><span class=\"kw-def\">RCP</span> + <span class=\"kw-alerte\">adrénaline IV bolus</span> selon protocole ACLS + appel 15</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Seuil décisionnel <span class=\"kw-alerte\">anaphylaxie</span></strong> ⚠️ — toute réaction <span class=\"kw-alerte\">≥ Grade II Ring &amp; Messmer</span> impose l'<span class=\"kw-ttt\">adrénaline IM immédiate</span> sans attendre la confirmation clinique. Le retard d'injection est le principal facteur de <span class=\"kw-def\">mortalité</span> — <span class=\"kw-ci\">ne jamais</span> surseoir pour faire un test, prendre une TA ou attendre un avis spécialisé.\n      </div>\n\n      <h5>Mode d'administration de l'<span class=\"kw-ttt\">adrénaline</span> auto-injectable</h5>\n      <ol>\n        <li><strong>Voie</strong> — <span class=\"kw-bio\">IM</span> exclusivement dans la <span class=\"kw-bio\">face antéro-latérale de la cuisse</span>.</li>\n        <li><strong>Posologie — stylo auto-injectable</strong> — adulte : <span class=\"kw-chiffre\">0,3 mg</span> (stylo <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>300</span> µg</span>) ; enfant <span class=\"kw-chiffre\">15-30 kg</span> : <span class=\"kw-chiffre\">0,15 mg</span> (stylo <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>150</span> µg</span>) ; à travers <span class=\"kw-clinique\">les</span> vêtements possible.</li>\n        <li><strong>Posologie — ampoule (contexte hospitalier / <span class=\"kw-alerte\">SAMU</span>)</strong> — <span class=\"kw-ttt\">0,01 mg/kg IM</span> (dose de référence), maximum <span class=\"kw-chiffre\">0,5 mg</span> chez l'adulte et <span class=\"kw-chiffre\">0,3 mg</span> chez l'enfant ; en IV titrée par bolus de 50-<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>100</span> µg</span> si <span class=\"kw-alerte\">choc</span> réfractaire ou <span class=\"kw-def\">Grade</span> IV.</li>\n        <li><strong>Renouvelable</strong> — toutes <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">5-15 min</span> si symptômes persistants ou réapparaissent.</li>\n        <li><strong>Appel du 15</strong> — systématique après toute injection d'<span class=\"kw-ttt\">adrénaline</span>.</li>\n        <li><strong>Position</strong> — allongée jambes surélevées, sauf si <span class=\"kw-clinique\">dyspnée</span> (semi-assise).</li>\n      </ol>\n\n      <div class=\"callout callout-warn\">\n        <strong>« Anaphylaxie ≠ <span class=\"kw-ci\">allergie</span> »</strong> ⚠️ — attention de ne pas confondre dans <span class=\"kw-clinique\">les</span> indications. Une <strong>allergie</strong> documentée n'impose pas l'<span class=\"kw-ttt\">adrénaline</span> si elle n'a jamais été <strong>anaphylactique</strong>. L'indication est sur le <span class=\"kw-alerte\">type et la sévérité antérieure de la réaction</span>, pas sur la simple positivité d'un test.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 187 — <span class=\"kw-ci\">Hypersensibilité</span>, allergies cutanées · 332 — Etat de <span class=\"kw-alerte\">choc</span></em></p>","frequence":1},{"id":"186-15","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités de diagnostic d’une conjonctivite allergique","contenu":"<p>La <span class=\"kw-def\">conjonctivite allergique</span> est l'expression oculaire d'une <strong>HS immédiate <span class=\"kw-chiffre\">IgE</span>-médiée</strong>. Le plus souvent <strong>bilatérale</strong>, associée à une rhinite <span class=\"kw-etio\">allergique</span> (rhino-conjonctivite), sur <span class=\"kw-def\">terrain</span> <span class=\"kw-clinique\">atopique</span>. Diagnostic essentiellement clinique, étayé par <span class=\"kw-clinique\">les</span> tests cutanés en cas de retentissement justifiant un bilan étiologique.</p>\n\n      <h5>Tableau clinique typique</h5>\n      <table >\n        <thead><tr><th>Signe</th><th>Description</th><th>Particularités</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Prurit oculaire</span></strong> ⭐</td>\n            <td>Symptôme cardinal — sensation de picotement, démangeaison, parfois intolérable</td>\n            <td>Signe d'orientation majeur, presque pathognomonique</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Larmoiement</span></strong></td>\n            <td>Hypersécrétion lacrymale claire, non purulente</td>\n            <td>Réflexe au <span class=\"kw-clinique\">prurit</span> + dégranulation mastocytaire</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Hyperhémie conjonctivale</span></strong></td>\n            <td>Rougeur conjonctivale diffuse, surtout en zone bulbaire</td>\n            <td>Bilatérale et symétrique le plus souvent</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Chémosis</span></strong></td>\n            <td><span class=\"kw-clinique\">Œdème</span> conjonctival translucide, parfois marqué</td>\n            <td>Signe d'inflammation aiguë</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Œdème palpébral</span></strong></td>\n            <td>Discret à modéré, bilatéral</td>\n            <td>Peut être plus marqué en cas d'angio-<span class=\"kw-clinique\">œdème</span> associé</td>\n          </tr>\n          <tr>\n            <td><strong>Photophobie</strong></td>\n            <td>Fréquente, surtout en phase aiguë</td>\n            <td>Modérée le plus souvent</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5>Formes cliniques selon la saisonnalité</h5>\n      <table >\n        <thead><tr><th>Forme</th><th>Allergènes</th><th><span class=\"kw-clinique\">Évolution</span></th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Saisonnière</strong> (intermittente)</td>\n            <td><span class=\"kw-etio\">Pollens</span> (graminées, bouleau, cyprès, herbacées)</td>\n            <td>Symptômes pendant le pic pollinique, résolution hors saison</td>\n          </tr>\n          <tr>\n            <td><strong>Perannuelle</strong> (persistante)</td>\n            <td><span class=\"kw-etio\">Acariens</span>, <span class=\"kw-etio\">phanères d'animaux</span>, <span class=\"kw-etio\">moisissures</span></td>\n            <td>Symptômes toute l'année, parfois fluctuants</td>\n          </tr>\n          <tr>\n            <td><strong>Professionnelle</strong></td>\n            <td>Latex, persulfates, farines, isocyanates</td>\n            <td>Symptômes au travail, amélioration le week-end/vacances</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5>Démarche diagnostique</h5>\n      <ol>\n        <li><strong>Anamnèse</strong> — caractérisation des symptômes (<span class=\"kw-clinique\">prurit</span> cardinal ++), <strong>bilatéralité</strong>, contexte saisonnier ou perannuel, association à <span class=\"kw-clinique\">rhinite</span>, ATCD personnels et familiaux d'<span class=\"kw-clinique\">atopie</span> (<span class=\"kw-clinique\">dermatite</span>, <span class=\"kw-def\">asthme</span>, autres allergies).</li>\n        <li><strong>Examen clinique</strong> — inspection conjonctivale, recherche d'une <span class=\"kw-clinique\">papille tarsienne</span> (forme chronique), absence de sécrétions purulentes, absence d'atteinte cornéenne sévère.</li>\n        <li><strong>Tests cutanés</strong> — <span class=\"kw-bio\">prick-tests</span> sur pneumallergènes ciblés selon l'anamnèse (acariens, pollens, animaux). Indispensables avant ITA.</li>\n        <li><strong><span class=\"kw-chiffre\">IgE</span> spécifiques</strong> — en 2ⁿᵈ intention si tests cutanés CI ou résultats discordants.</li>\n      </ol>\n\n      <h5>Diagnostics différentiels essentiels</h5>\n      <table >\n        <thead><tr><th>Diagnostic</th><th>Distinction clé</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Conjonctivite infectieuse <span class=\"kw-etio\">bactérienne</span></strong></td><td><span class=\"kw-clinique\">Sécrétions purulentes</span> ++, unilatérale fréquente, <span class=\"kw-ci\">pas de prurit</span></td></tr>\n          <tr><td><strong>Conjonctivite <span class=\"kw-etio\">virale</span></strong></td><td><span class=\"kw-clinique\">Adénopathie</span> pré-auriculaire, contexte épidémique, sécrétions claires</td></tr>\n          <tr><td><strong>Kérato-conjonctivite vernale</strong></td><td>Enfant, garçon ++, atteinte cornéenne, papilles géantes, photophobie marquée</td></tr>\n          <tr><td><strong>Syndrome sec</strong></td><td>Adulte âgé, brûlure plus que <span class=\"kw-clinique\">prurit</span>, <span class=\"kw-ci\">test de Schirmer pathologique</span></td></tr>\n          <tr><td><strong>Conjonctivite irritative</strong></td><td><span class=\"kw-def\">Contact</span> chimique, polluants, pas de <span class=\"kw-clinique\">prurit</span> isolé, contexte d'exposition aiguë</td></tr>\n        </tbody>\n      </table>\n\n      <h5>Association à connaître : rhino-conjonctivite <span class=\"kw-etio\">allergique</span></h5>\n      <ul>\n        <li><strong>Fréquence</strong> — la conjonctivite est associée à une <span class=\"kw-clinique\">rhinite allergique</span> dans la grande majorité des cas (&gt;<span class=\"kw-chiffre\"> 80 %</span>).</li>\n        <li><strong>Présentation</strong> — éternuements, rhinorrhée claire, <span class=\"kw-clinique\">prurit</span> nasal, obstruction nasale + <span class=\"kw-clinique\">prurit</span> oculaire et larmoiement.</li>\n        <li><strong><span class=\"kw-def\">Comorbidité</span></strong> — risque accru d'<span class=\"kw-clinique\">asthme allergique</span> (marche <span class=\"kw-etio\">atopique</span>).</li>\n        <li><strong>Bilan</strong> — exploration commune à la rhinite (prick + <span class=\"kw-chiffre\">IgE</span>).</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>Drapeaux d'orientation</strong> — devant une conjonctivite, le <span class=\"kw-clinique\">prurit oculaire bilatéral</span> est le signe le plus évocateur d'une étiologie <span class=\"kw-etio\">allergique</span>. Une <span class=\"kw-alerte\">atteinte cornéenne sévère</span>, des <span class=\"kw-alerte\">papilles géantes</span>, une <span class=\"kw-alerte\">forme unilatérale</span> ou des <span class=\"kw-alerte\">sécrétions purulentes</span> doivent orienter vers un autre diagnostic et imposer un avis ophtalmologique.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 188 — <span class=\"kw-def\">Asthme</span> - Rhinite</em></p>","frequence":0},{"id":"186-16","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes du traitement d’une conjonctivite allergique","contenu":"<p>Le traitement de la <span class=\"kw-def\">conjonctivite allergique</span> repose sur une démarche en trois niveaux : <strong>(1) éviction allergénique</strong> et <strong>lavage oculaire</strong>, <strong>(2) traitement symptomatique</strong> (antiH<span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>1</span> l</span>ocaux ± oraux, cromones), <strong>(3) traitement étiologique</strong> par immunothérapie allergénique (ITA) si rhino-conjonctivite saisonnière sévère mal contrôlée.</p>\n\n      <h5>Stratégie thérapeutique étagée</h5>\n      <table >\n        <thead><tr><th>Niveau</th><th>Mesure</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>1 — Éviction</strong></td>\n            <td><span class=\"kw-bio\">Éviction de l'allergène</span> identifié quand possible</td>\n            <td>\n              <strong>Acariens :</strong> housses anti-acariens, lavage draps <span class=\"kw-chiffre\">≥ 60 °C</span>, aspiration HEPA<br>\n              <strong>Pollens :</strong> sécher le linge à l'intérieur, fermer <span class=\"kw-clinique\">les</span> fenêtres en pic pollinique<br>\n              <strong>Animaux :</strong> ne pas accéder à la chambre, lavage régulier\n            </td>\n          </tr>\n          <tr>\n            <td><strong>1 — Lavage</strong></td>\n            <td>Lavage oculaire au <span class=\"kw-ttt\">sérum physiologique</span></td>\n            <td>Plusieurs fois par jour pendant la phase symptomatique — élimine mécaniquement l'allergène et <span class=\"kw-clinique\">les</span> médiateurs locaux</td>\n          </tr>\n          <tr>\n            <td><strong>2 — Antihistaminiques locaux</strong></td>\n            <td>\n              <span class=\"kw-ttt\">Lévocabastine</span> (collyre)<br>\n              <span class=\"kw-ttt\">Olopatadine</span> (collyre, double action antiH1 + stabilisateur mastocytaire)<br>\n              <span class=\"kw-ttt\">Azélastine</span>\n            </td>\n            <td>Action rapide, bonne tolérance, en <span class=\"kw-chiffre\">première intention</span> dans la forme isolée</td>\n          </tr>\n          <tr>\n            <td><strong>2 — Cromones locales</strong></td>\n            <td><span class=\"kw-ttt\">Cromoglycate de sodium</span></td>\n            <td>Stabilisateur mastocytaire — intérêt en prévention avant exposition (saisonnière)</td>\n          </tr>\n          <tr>\n            <td><strong>2 — Antihistaminiques oraux</strong></td>\n            <td>AntiH1 de <span class=\"kw-ttt\">2ᵉ génération</span> (cétirizine, loratadine, desloratadine, fexofénadine, bilastine)</td>\n            <td>Indiqués si rhino-conjonctivite (action systémique sur <span class=\"kw-clinique\">les</span> deux atteintes), bonne tolérance (somnolence rare)</td>\n          </tr>\n          <tr>\n            <td><strong>3 — <span class=\"kw-ttt\">Corticoïdes</span> locaux</strong></td>\n            <td>Collyres <span class=\"kw-ttt\">corticoïdes</span></td>\n            <td>\n              <span class=\"kw-ci\">À ne prescrire que si certitude diagnostique</span> ⚠️<br>\n              Après échec des traitements précédents<br>\n              <span class=\"kw-ci\">Avis ophtalmologique obligatoire</span> (risque : glaucome cortisonique, cataracte, infection)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>3 — ITA</strong></td>\n            <td><span class=\"kw-bio\">Immunothérapie allergénique</span> (voie sublinguale, plus rarement SC)</td>\n            <td>\n              Indiquée pour <strong>rhino-conjonctivite saisonnière persistante modérée à sévère</strong> malgré antiH1 et <span class=\"kw-ttt\">corticoïdes</span> nasaux<br>\n              Durée : <span class=\"kw-chiffre\">3 à 5 ans</span><br>\n              Permet la <strong><span class=\"kw-ttt\">réduction</span> des symptômes</strong>, la <strong>diminution de la consommation médicamenteuse</strong> et la <strong>prévention de l'apparition d'un <span class=\"kw-def\">asthme</span></strong>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5>Antihistaminiques <span class=\"kw-chiffre\">H1</span> — généralités</h5>\n      <ul>\n        <li><strong>Indications</strong> — actif sur le <span class=\"kw-clinique\">prurit</span>, <span class=\"kw-clinique\">les</span> éternuements, la rhinorrhée et les symptômes oculaires.</li>\n        <li><strong>Limites</strong> — <span class=\"kw-ci\">peu actif sur l'obstruction nasale</span> (préférer alors <span class=\"kw-clinique\">les</span> <span class=\"kw-ttt\">corticoïdes</span> nasaux).</li>\n        <li><strong>Antihistaminiques de 2ᵉ génération</strong> — bonne tolérance, somnolence rare, possibilité de stimulation de l'appétit parfois.</li>\n        <li><strong>Voies d'administration</strong> — orale ou locale (collyres, solutions nasales).</li>\n      </ul>\n\n      <h5><span class=\"kw-ttt\">Corticoïdes</span> — généralités</h5>\n      <ul>\n        <li><strong>Voie locale</strong> (nasale, oculaire, inhalée) — traitement de choix de l'<span class=\"kw-def\">asthme</span> lorsqu'un traitement de fond est indiqué.</li>\n        <li><strong>Voie systémique</strong> — traitement de l'<span class=\"kw-alerte\">urgence</span> (<span class=\"kw-alerte\">anaphylaxie</span>, exacerbation sévère), <span class=\"kw-ci\">à éviter au long cours</span> en raison des effets secondaires.</li>\n      </ul>\n\n      <h5>Immunothérapie allergénique (ITA) — points essentiels</h5>\n      <table >\n        <thead><tr><th>Item</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Principe</strong></td>\n            <td>Administration de <span class=\"kw-bio\">doses croissantes</span> de l'allergène → induction d'une <span class=\"kw-bio\">tolérance immunitaire</span> (réorientation Th2 → Th1, ↑ <span class=\"kw-chiffre\">IgG</span>4 bloquantes, induction de LT régulateurs)</td>\n          </tr>\n          <tr>\n            <td><strong>Voies</strong></td>\n            <td>\n              <span class=\"kw-bio\">Sublinguale liquide</span> (acariens, pollens, animaux)<br>\n              <span class=\"kw-bio\">Sublinguale comprimés</span> (acariens et graminées uniquement — 1ʳᵉ prise sous <span class=\"kw-def\">surveillance</span> médicale <span class=\"kw-chiffre\">30 min</span>)<br>\n              <span class=\"kw-bio\">SC</span> (non remboursée sauf venins d'hyménoptères)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Conditions</strong></td>\n            <td>Monoallergique ou allergène dominant identifié ; éviction impossible ; pression thérapeutique forte</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-ci\">CI absolues</span></strong></td>\n            <td><span class=\"kw-ci\">Grossesse (début)</span>, immunodépression sévère, MAI systémique, néoplasie, troubles psychiatriques sévères, <span class=\"kw-ci\">asthme non contrôlé</span> (CI transitoire)</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-ci\">CI relatives</span></strong></td>\n            <td><span class=\"kw-def\">Asthme</span> sévère contrôlé, <span class=\"kw-ttt\">β-bloquants</span>, <span class=\"kw-clinique\">eczéma</span> sévère, maladies cardiovasculaires graves, immunodéficiences en <span class=\"kw-clinique\">rémission</span></td>\n          </tr>\n          <tr>\n            <td><strong>Âge minimum</strong></td>\n            <td>ITA aux pneumallergènes : <strong>à partir de <span class=\"kw-chiffre\">5 ans</span></strong></td>\n          </tr>\n          <tr>\n            <td><strong>Évaluation</strong></td>\n            <td>Efficacité doit être démontrée dans la <strong>1ʳᵉ année</strong> (<span class=\"kw-ttt\">réduction</span> des symptômes et/ou de la consommation médicamenteuse) — sinon <span class=\"kw-ci\">interruption</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Bénéfice unique de l'ITA</strong> ✅ — seul traitement <strong>modifiant l'histoire naturelle</strong> de l'<span class=\"kw-ci\">allergie</span> : limite l'apparition de nouvelles sensibilisations et la progression vers de nouvelles manifestations (<span class=\"kw-def\">asthme</span>). La <span class=\"kw-bio\">polysensibilisation n'est PAS une contre-indication</span> à l'ITA si un allergène dominant est identifié.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 188 — <span class=\"kw-def\">Asthme</span> - Rhinite</em></p>","frequence":0},{"id":"186-17","rang":"A","rubrique":"Pédiatrie — Epidémiologie","titre":"Connaître les grandes tendances épidémiologiques de l’allergie alimentaire : prévalence, mortalité, allergènes","contenu":"<p>L'<span class=\"kw-def\">allergie alimentaire pédiatrique</span> est la première maladie <span class=\"kw-etio\">atopique</span> du nourrisson et concerne <span class=\"kw-chiffre\">5 à 7 %</span> des enfants français. Le pic est à <span class=\"kw-chiffre\">6-10 ans (7 %)</span>. L'<span class=\"kw-clinique\">évolution</span> dépend de l'allergène : <strong>transitoire</strong> pour lait et œuf (~<span class=\"kw-chiffre\">80 %</span> guérison), <strong>persistante</strong> pour arachide, fruits à coque, poissons et crustacés.</p>\n\n      <h5><span class=\"kw-def\">Prévalence</span> pédiatrique par tranche d'âge</h5>\n      <table >\n        <thead><tr><th>Âge</th><th>Prévalence</th><th>Allergènes dominants</th><th><span class=\"kw-clinique\">Évolution</span> attendue</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-chiffre\">2–5 ans</span></strong></td><td><span class=\"kw-chiffre\">4 %</span></td><td>Lait de vache (résiduel), œuf, arachide émergente</td><td>APLV et œuf : guérison ~<span class=\"kw-chiffre\">80 %</span> avant <span class=\"kw-chiffre\">3 ans</span></td></tr>\n          <tr><td><strong><span class=\"kw-chiffre\">6–10 ans</span></strong></td><td><span class=\"kw-chiffre\">7 %</span> ⭐ <em>(pic)</em></td><td>Arachide, fruits à coque, poissons</td><td>Persistance pour arachide / FAC / poissons / crustacés</td></tr>\n          <tr><td><strong><span class=\"kw-chiffre\">11–14 ans</span></strong></td><td><span class=\"kw-chiffre\">3,5 %</span></td><td>Allergies persistantes + émergence des fruits frais</td><td>Décrue post-guérison des allergies du nourrisson</td></tr>\n        </tbody>\n      </table>\n\n      <h5>Cartographie des allergènes par âge pédiatrique</h5>\n      <table >\n        <thead><tr><th>Âge</th><th>Allergènes principaux</th><th>Particularités</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>&lt;<span class=\"kw-chiffre\"> 6 mois</span></strong></td>\n            <td><span class=\"kw-etio\">Lait de vache</span></td>\n            <td>APLV — caséine, α-lactalbumine, β-lactoglobuline ; éviction des produits laitiers d'origine animale (chèvre/brebis aussi)</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-chiffre\">5–15 mois</span></strong></td>\n            <td><span class=\"kw-etio\">Œuf</span> (1ᵉʳ), <span class=\"kw-etio\">arachide</span>, lait de vache, <span class=\"kw-etio\">moutarde</span>, <span class=\"kw-etio\">morue</span></td>\n            <td>Œuf : ovalbumine (thermolabile) <span class=\"kw-bio\">vs</span> ovomucoïde (thermorésistant) — distinction pratique pour la cuisson</td>\n          </tr>\n          <tr>\n            <td><strong>&gt;<span class=\"kw-chiffre\"> 1 an</span></strong></td>\n            <td><span class=\"kw-etio\">Arachide</span> devient le 1ᵉʳ allergène alimentaire</td>\n            <td>Ara h 2 = marqueur de gravité anaphylactique</td>\n          </tr>\n          <tr>\n            <td><strong>&gt;<span class=\"kw-chiffre\"> 3 ans</span></strong></td>\n            <td>Arachide, fruits à coque, poissons, crustacés, kiwi</td>\n            <td>Allergies plus durables qu'au nourrisson</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5><span class=\"kw-def\">Mortalité</span> et morbidité pédiatriques</h5>\n      <ul>\n        <li><strong>1ʳᵉ cause de décès anaphylactique chez l'enfant</strong> — devant <span class=\"kw-clinique\">les</span> hyménoptères et les médicaments.</li>\n        <li><strong>Allergène le plus mortel</strong> — <span class=\"kw-alerte\">arachide</span> et <span class=\"kw-alerte\">fruits à coque</span>.</li>\n        <li><strong>SEIPA</strong> 🔥 — Syndrome d'Entérocolite Induite par <span class=\"kw-clinique\">les</span> Protéines Alimentaires — forme aiguë spectaculaire avec <span class=\"kw-clinique\">vomissements en jet 1-4 h après ingestion</span> + <span class=\"kw-clinique\">pâleur</span> + léthargie + <span class=\"kw-clinique\">déshydratation</span> ; <span class=\"kw-bio\">diarrhée 5-10 h plus tard</span> ; non-<span class=\"kw-chiffre\">IgE</span> médié principalement.</li>\n        <li><strong>Œsophagite à <span class=\"kw-bio\">éosinophiles</span></strong> — <span class=\"kw-def\">terrain</span> <span class=\"kw-etio\">atopique</span> dans <span class=\"kw-chiffre\">50-80 %</span>, <span class=\"kw-clinique\">dyspnée</span> alimentaire, <span class=\"kw-bio\">biopsie</span> : <span class=\"kw-chiffre\">&gt; 15 PNE/champ</span> au grossissement 400×.</li>\n      </ul>\n\n      <h5><span class=\"kw-clinique\">Évolution</span> naturelle — <span class=\"kw-def\">pronostic</span> par allergène</h5>\n      <table >\n        <thead><tr><th>Allergène</th><th>Pronostic</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Lait de vache (APLV)</strong></td><td><span class=\"kw-chiffre\">~80 % de guérison</span> avant <span class=\"kw-chiffre\">3 ans</span></td></tr>\n          <tr><td><strong>Œuf</strong></td><td><span class=\"kw-chiffre\">~80 % de guérison</span> avant <span class=\"kw-chiffre\">5 ans</span></td></tr>\n          <tr><td><strong>Arachide</strong></td><td><span class=\"kw-alerte\">~80 % de persistance</span> à vie</td></tr>\n          <tr><td><strong>Fruits à coque</strong></td><td><span class=\"kw-alerte\">Persistance ~80 %</span></td></tr>\n          <tr><td><strong>Poissons / crustacés</strong></td><td><span class=\"kw-alerte\">Persistance le plus souvent</span></td></tr>\n        </tbody>\n      </table>\n\n      <h5>Facteurs environnementaux pédiatriques</h5>\n      <ul>\n        <li><strong><span class=\"kw-etio\"><span class=\"kw-etio\">Tabagisme</span> passif</span></strong> (prénatal et post-natal) — <span class=\"kw-def\">facteur de risque</span>.</li>\n        <li><strong>Théorie hygiéniste</strong> — baisse des contacts <span class=\"kw-etio\">infectieux</span> et de la biodiversité microbienne dans l'enfance corrélée à l'atopie.</li>\n        <li><strong>Facteurs protecteurs</strong> — enfants <span class=\"kw-clinique\">les</span> plus jeunes d'une fratrie (contage <span class=\"kw-etio\">infectieux</span> des aînés), <span class=\"kw-bio\">crèche</span> (contage précoce), milieu <span class=\"kw-bio\">rural</span> riche en endotoxines bactériennes (« effet ferme »).</li>\n        <li><strong><span class=\"kw-ci\">Allaitement</span> maternel exclusif <span class=\"kw-chiffre\">4-6 mois</span></strong> — recommandé ; <span class=\"kw-ci\">pas d'exclusion alimentaire chez la femme allaitante</span>.</li>\n        <li><strong>Diversification <span class=\"kw-chiffre\">4-6 mois</span></strong> — sans différer l'introduction d'aliments dits allergisants (recommandation actualisée — diversification précoce protectrice).</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>Marche <span class=\"kw-etio\">atopique</span></strong> ⚠️ — la succession des manifestations atopiques chez un enfant : <span class=\"kw-clinique\">dermatite atopique</span> (nourrisson) → <span class=\"kw-clinique\">allergie alimentaire</span> → <span class=\"kw-clinique\">asthme</span> (<span class=\"kw-chiffre\">3-4 ans</span>) → <span class=\"kw-clinique\">rhino-conjonctivite</span> (adolescence). Le SEIPA et l'APLV évoluent généralement vers la guérison, mais la <span class=\"kw-clinique\">dermatite</span> <span class=\"kw-clinique\">atopique</span> précède souvent l'<span class=\"kw-def\">asthme</span>.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 187 — <span class=\"kw-ci\">Hypersensibilité</span>, allergies cutanées · 188 — <span class=\"kw-def\">Asthme</span> - Rhinite · 332 — Etat de <span class=\"kw-alerte\">choc</span></em></p>","frequence":0},{"id":"186-18","rang":"A","rubrique":"Pédiatrie — Epidémiologie","titre":"Connaître les grandes tendances épidémiologiques de l’allergie respiratoire : prévalence, mortalité, morbidité, allergènes","contenu":"<p>L'<span class=\"kw-def\">allergie respiratoire</span> est la maladie chronique la plus fréquente de l'enfant. La <span class=\"kw-bio\">prévalence a doublé en 20 ans</span> du fait de l'<span class=\"kw-clinique\">évolution</span> environnementale. L'<span class=\"kw-def\">asthme</span> <span class=\"kw-etio\">allergique</span> pédiatrique débute typiquement <span class=\"kw-chiffre\">vers 3-4 ans</span>, dans le cadre d'une <strong>marche <span class=\"kw-etio\">atopique</span></strong> initiée par la <span class=\"kw-clinique\">dermatite</span> <span class=\"kw-clinique\">atopique</span>.</p>\n\n      <h5>Données épidémiologiques pédiatriques</h5>\n      <table >\n        <thead><tr><th>Paramètre</th><th>Valeur</th><th>Commentaire</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Atopie (<span class=\"kw-chiffre\">≥ 1</span> test cutané positif)</strong></td><td><span class=\"kw-chiffre\">30–40 %</span></td><td>Population française générale</td></tr>\n          <tr><td><strong>Allergies chez l'enfant &lt;<span class=\"kw-chiffre\"> 15 ans</span></strong></td><td><span class=\"kw-chiffre\">30 %</span></td><td>Toutes allergies confondues (alimentaires + respiratoires + cutanées)</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Asthme</span> <span class=\"kw-etio\">allergique</span> pédiatrique</strong></td><td><span class=\"kw-chiffre\">11 %</span></td><td>1ʳᵉ maladie chronique de l'enfant en France</td></tr>\n          <tr><td><strong>Rhinite <span class=\"kw-etio\">allergique</span> pédiatrique</strong></td><td><span class=\"kw-chiffre\">~25 %</span></td><td>Souvent sous-diagnostiquée</td></tr>\n          <tr><td><strong>Co-<span class=\"kw-def\">morbidité</span> rhinite + <span class=\"kw-def\">asthme</span></strong></td><td><span class=\"kw-chiffre\">~80 %</span></td><td><span class=\"kw-clinique\">Les</span> asthmatiques sont rhinitiques dans <span class=\"kw-chiffre\">80 %</span> des cas</td></tr>\n          <tr><td><strong>Tendance temporelle</strong></td><td>×2 en <span class=\"kw-chiffre\">20 ans</span></td><td><span class=\"kw-clinique\">Évolution</span> des expositions environnementales</td></tr>\n        </tbody>\n      </table>\n\n      <h5>Marche <span class=\"kw-etio\">atopique</span> : succession des manifestations</h5>\n      <ol>\n        <li><strong>Étape 1 — <span class=\"kw-def\">Terrain</span> de <span class=\"kw-clinique\">dermatite atopique</span></strong> (nourrisson, <span class=\"kw-chiffre\">≤ 1 an</span>) — souvent inaugurale.</li>\n        <li><strong>Étape 2 — <span class=\"kw-clinique\">Allergies alimentaires</span></strong> (nourrisson,<span class=\"kw-chiffre\"> 1-2 ans</span>) — APLV, œuf, arachide.</li>\n        <li><strong>Étape 3 — <span class=\"kw-clinique\">Asthme allergique</span></strong> — émerge typiquement vers <span class=\"kw-chiffre\">3-4 ans</span>.</li>\n        <li><strong>Étape 4 — <span class=\"kw-clinique\">Rhino-conjonctivite allergique</span></strong> — à l'<span class=\"kw-chiffre\">adolescence</span>.</li>\n      </ol>\n\n      <p><em>La marche <span class=\"kw-etio\">atopique</span> est une <span class=\"kw-bio\">notion statistique</span> sans valeur pronostique pour un patient donné. <span class=\"kw-clinique\">Les</span> enfants atteints d'APLV guérissent souvent spontanément sans devenir asthmatiques.</em></p>\n\n      <h5>Principaux allergènes respiratoires pédiatriques</h5>\n      <table >\n        <thead><tr><th>Type</th><th>Allergènes</th><th>Particularités pédiatriques</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Domestiques (perannuels)</strong></td>\n            <td><span class=\"kw-etio\">Acariens</span> ++, <span class=\"kw-etio\">phanères d'animaux</span> (chat, chien), <span class=\"kw-etio\">moisissures</span></td>\n            <td>Acariens = allergène le plus fréquent ; <span class=\"kw-etio\">Alternaria</span> = marqueur de gravité asthmatique pédiatrique</td>\n          </tr>\n          <tr>\n            <td><strong>Extérieurs (saisonniers)</strong></td>\n            <td><span class=\"kw-etio\">Pollens d'arbres</span> (bouleau, cyprès), <span class=\"kw-etio\">graminées</span>, <span class=\"kw-etio\">herbacées</span> (armoise, ambroisie)</td>\n            <td>Apparition plus tardive (post-puberté) que <span class=\"kw-clinique\">les</span> allergènes domestiques</td>\n          </tr>\n          <tr>\n            <td><strong>Infections virales</strong></td>\n            <td>Rhinovirus, VRS, SARS-CoV-2</td>\n            <td>Déclencheurs majeurs d'exacerbations asthmatiques chez l'enfant</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5><span class=\"kw-clinique\">Évolution</span> naturelle de l'<span class=\"kw-ci\">allergie</span> respiratoire</h5>\n      <ul>\n        <li><strong><span class=\"kw-clinique\">Dermatite</span> <span class=\"kw-etio\">atopique</span></strong> — disparaît dans la majorité des cas dans la petite enfance.</li>\n        <li><strong><span class=\"kw-def\">Asthme</span> <span class=\"kw-etio\">allergique</span></strong> — <span class=\"kw-alerte\">tendance à persister</span> à l'âge adulte, surtout si débuté tardivement ou avec sensibilisation aux pneumallergènes.</li>\n        <li><strong>Rhino-conjonctivite</strong> — persiste généralement à l'âge adulte.</li>\n        <li><strong>Facteurs de persistance</strong> — sexe féminin, <span class=\"kw-etio\"><span class=\"kw-etio\">tabagisme</span> actif</span> précoce, hyperréactivité bronchique persistante.</li>\n      </ul>\n\n      <h5><span class=\"kw-def\">Mortalité</span> et morbidité</h5>\n      <ul>\n        <li><strong><span class=\"kw-def\">Asthme</span></strong> — <span class=\"kw-chiffre\">~1000 décès/an</span> en France, en baisse, considérés comme évitables.</li>\n        <li><strong><span class=\"kw-def\"><span class=\"kw-def\">Asthme</span> aigu grave</span> pédiatrique</strong> — surreprésentation en milieu socio-économique défavorisé.</li>\n        <li><strong>Retentissement</strong> — absentéisme scolaire, performance, qualité de vie familiale, hospitalisations répétées.</li>\n      </ul>\n\n      <h5><span class=\"kw-def\">Facteurs de risque</span> pédiatriques spécifiques</h5>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Facteurs</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Génétiques</strong></td>\n            <td>Polygénique — <span class=\"kw-chiffre\">10 %</span> sans parent asthmatique, <span class=\"kw-chiffre\">25 %</span> avec 1 parent, <span class=\"kw-chiffre\">&gt; 50 %</span> avec 2 parents</td>\n          </tr>\n          <tr>\n            <td><strong>Environnementaux</strong></td>\n            <td>Infections virales (favorisent HRB durable), <span class=\"kw-etio\">tabagisme</span> parental périnatal, pollution intérieure (parfums, ménagers), pollution atmosphérique, altération du microbiote</td>\n          </tr>\n          <tr>\n            <td><strong>Effort</strong></td>\n            <td>Bronchospasme chez <span class=\"kw-chiffre\">&gt; 80 %</span> des enfants asthmatiques (<span class=\"kw-def\">air</span> froid + sec)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Bénéfice préventif de l'ITA</strong> ✅ — chez l'enfant avec rhino-conjonctivite <span class=\"kw-etio\">allergique</span> aux pollens, l'<span class=\"kw-bio\">immunothérapie allergénique</span> a démontré sa capacité à <strong>prévenir l'apparition d'un <span class=\"kw-def\">asthme</span></strong>. Indication majeure en pédiatrie ⭐.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 187 — <span class=\"kw-ci\">Hypersensibilité</span>, allergies cutanées · 188 — <span class=\"kw-def\">Asthme</span> - Rhinite</em></p>","frequence":0},{"id":"186-19","rang":"A","rubrique":"Pédiatrie — Examens complémentaires","titre":"Connaître l’indication de la réalisation d’un test de dépistage IgE multiallergénique (aéroallergènes et trophallergènes)","contenu":"<p>En pédiatrie, <span class=\"kw-clinique\">les</span> <span class=\"kw-def\">tests multi-allergéniques IgE</span> (Phadiatop, Trophatop, Phadiatop Infant) sont particulièrement utiles lorsque le <strong>prick-test</strong> est limité techniquement (très jeune enfant), <span class=\"kw-ci\">contre-indiqué</span> (<span class=\"kw-clinique\">eczéma</span> sévère diffus, dermographisme) ou non interprétable (antihistaminiques non sevrables). Permettent un <span class=\"kw-bio\">dépistage atopique</span> de débrouillage.</p>\n\n      <h5>Tests disponibles et indications pédiatriques</h5>\n      <table >\n        <thead><tr><th>Test</th><th>Panel couvert</th><th>Indication pédiatrique privilégiée</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Phadiatop</strong></td>\n            <td><span class=\"kw-bio\">Aéroallergènes</span> — acariens, pollens (arbres, graminées, herbacées), chat, chien, moisissures, blattes</td>\n            <td>Enfant suspect d'<span class=\"kw-clinique\">atopie respiratoire</span> (<span class=\"kw-def\">asthme</span>, rhinite) sans cible évidente</td>\n          </tr>\n          <tr>\n            <td><strong>Trophatop</strong></td>\n            <td><span class=\"kw-bio\">Trophallergènes</span> — lait de vache, œuf, arachide, soja, blé, poissons, crustacés</td>\n            <td>Enfant suspect d'<span class=\"kw-clinique\">allergie alimentaire</span> ou de SEIPA</td>\n          </tr>\n          <tr>\n            <td><strong>Phadiatop Infant</strong> ⭐</td>\n            <td><span class=\"kw-bio\">Aéroallergènes + trophallergènes</span> regroupés</td>\n            <td>Test de choix chez le <span class=\"kw-clinique\">nourrisson</span> et le <span class=\"kw-clinique\">jeune enfant</span> avec symptômes mixtes ou non spécifiques</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5>Indications spécifiquement pédiatriques</h5>\n      <ul>\n        <li><strong>Très jeune enfant</strong> — le prick-test est réalisable <span class=\"kw-bio\">dès l'âge de 3 mois</span>, mais sa sensibilité est limitée chez le nourrisson. Le multi-allergénique offre une alternative non invasive.</li>\n        <li><strong><span class=\"kw-clinique\">Eczéma</span> diffus sévère</strong> — <span class=\"kw-ci\">CI au prick</span> (peau non saine, dermographisme associé). Test <span class=\"kw-ttt\">biologique</span> = alternative.</li>\n        <li><strong>Dermographisme</strong> — faux positifs systématiques au prick → préférer l'<span class=\"kw-chiffre\">IgE</span>.</li>\n        <li><strong>Antihistaminiques non sevrables</strong> — chez l'enfant traité au long cours, faux négatifs des pricks.</li>\n        <li><strong>Suspicion d'<span class=\"kw-clinique\">atopie multiple</span></strong> — symptômes cutanés + respiratoires + digestifs → <span class=\"kw-def\">dépistage</span> rapide.</li>\n        <li><strong>Bilan pré-désensibilisation</strong> — orientation initiale avant tests cutanés ciblés et bilan moléculaire.</li>\n      </ul>\n\n      <h5>Hiérarchie diagnostique pédiatrique</h5>\n      <table >\n        <thead><tr><th>Niveau</th><th>Examen</th><th>Quand</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>1</strong></td>\n            <td>Anamnèse + examen clinique</td>\n            <td>Toujours en <span class=\"kw-chiffre\">première intention</span></td>\n          </tr>\n          <tr>\n            <td><strong>2 (préférentiel)</strong></td>\n            <td><span class=\"kw-bio\">Prick-tests</span></td>\n            <td>Si réalisables techniquement et sans CI</td>\n          </tr>\n          <tr>\n            <td><strong>2 (alternatif)</strong></td>\n            <td><span class=\"kw-bio\">Multi-allergénique IgE</span> (Phadiatop / Trophatop / Phadiatop Infant)</td>\n            <td>Si prick CI/impossible OU pour <strong><span class=\"kw-def\">dépistage</span> <span class=\"kw-etio\">atopique</span></strong> rapide</td>\n          </tr>\n          <tr>\n            <td><strong>3</strong></td>\n            <td><span class=\"kw-chiffre\">IgE</span> spécifiques ciblées + recombinants</td>\n            <td>Si multi-allergénique positif ou pour préciser une sensibilisation</td>\n          </tr>\n          <tr>\n            <td><strong>4</strong></td>\n            <td>Test de provocation orale (TPO)</td>\n            <td>En centre spécialisé, si diagnostic incertain ou évaluation de tolérance <span class=\"kw-etio\">acquise</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h5>Interprétation des résultats</h5>\n      <ul>\n        <li><strong>Phadiatop / Trophatop / Phadiatop Infant positif</strong> — sensibilisation à au moins un allergène du panel ; sensibilité &gt;<span class=\"kw-chiffre\"> 90 %</span> pour <span class=\"kw-clinique\">les</span> principales atopies.</li>\n        <li><strong>Test négatif</strong> — rend une atopie peu probable, mais <span class=\"kw-ci\">n'exclut pas formellement</span> une <span class=\"kw-ci\">allergie</span> à un allergène non couvert (médicament, venin, latex, allergène rare).</li>\n        <li><strong>Étape suivante en cas de positivité</strong> — <span class=\"kw-bio\">IgE spécifiques contre les composants individuels</span> du panel pour identifier le(s) allergène(s) responsable(s).</li>\n      </ul>\n\n      <h5>Examens à NE PAS prescrire chez l'enfant</h5>\n      <ul>\n        <li><strong><span class=\"kw-bio\">IgE totales sériques</span></strong> ❌ — inutiles, non remboursées.</li>\n        <li><strong><span class=\"kw-bio\">Polynucléaires</span> <span class=\"kw-bio\">éosinophiles</span></strong> — non recommandés pour le diagnostic.</li>\n        <li><strong><span class=\"kw-chiffre\">IgG</span> spécifiques</strong> ❌ — aucune indication en allergologie pédiatrique courante.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>Stratégie optimale pédiatrique</strong> — le <strong>Phadiatop Infant</strong> est l'outil de débrouillage de choix chez le nourrisson et le jeune enfant <span class=\"kw-etio\">atopique</span> polysymptomatique. Sa positivité oriente le bilan ciblé ; sa négativité réoriente vers une étiologie non <span class=\"kw-chiffre\">IgE</span> ou non allergique. Toujours en <span class=\"kw-bio\">complément</span> (et non en remplacement) de l'<strong>anamnèse</strong> ⭐.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 187 — <span class=\"kw-ci\">Hypersensibilité</span>, allergies cutanées · 188 — <span class=\"kw-def\">Asthme</span> - Rhinite</em></p>","frequence":0}],"astuces":[],"strategie":{"urgence":"<p><strong>Degré :</strong> <span class='kw-alerte'>Anaphylaxie</span> = <span class=\"kw-alerte\">urgence</span> vitale ; <span class='kw-chiffre'><span class=\"kw-chiffre\">10-40%</span></span> des chocs anaphylactiques sont d'origine <span class='kw-etio'>alimentaire</span><br><strong>Fenêtre :</strong> réaction <span class='kw-etio'>IgE-médiée</span> typiquement <span class='kw-chiffre'>&lt;<span class=\"kw-chiffre\"> 1h</span></span> (parfois quelques heures) ; <span class='kw-etio'>SEIPA</span> aigu <span class='kw-chiffre'><span class=\"kw-chiffre\">1-4h</span></span> après ingestion<br><strong>1er geste :</strong> <span class='kw-ttt'>Adrénaline IM</span> dès l'<span class=\"kw-alerte\">anaphylaxie</span> sévère (<span class=\"kw-def\">grade</span> 4, <span class=\"kw-chiffre\">grade 3</span>, grade 2 avec <span class='kw-chiffre'>≥ 2 organes</span>)</p>","hospit":"<p><strong>Ambulatoire :</strong> bilan allergologique standard — <span class='kw-ttt'>prick-tests</span> (réalisables à tout âge) ; <span class='kw-bio'>dosage des IgE spécifiques</span> en 2nde intention<br><strong>Hospit / spécialisé :</strong> tests à risque — <span class='kw-ttt'>IDR</span>, <span class='kw-ttt'>test de provocation</span> (<span class=\"kw-def\">surveillance</span> <span class='kw-chiffre'><span class=\"kw-chiffre\">2-4h</span></span>), <span class='kw-ttt'>ITA venins</span> en rush ; réintroduction <span class='kw-etio'>APLV</span> <span class=\"kw-chiffre\">IgE</span>-médiée ou sévère en milieu hospitalier<br><strong><span class=\"kw-alerte\">Urgence</span> :</strong> réaction systémique ou <span class='kw-alerte'><span class=\"kw-alerte\">anaphylaxie</span></span> → <span class='kw-ttt'><span class=\"kw-ttt\">adrénaline</span> IM</span> + surveillance hospitalière</p>","redflags":"<ul><li><span class='kw-alerte'>Anaphylaxie</span> : <span class=\"kw-clinique\">hypotension</span>, bronchospasme, <span class=\"kw-clinique\">œdème</span> laryngé (œdème de Quincke), <span class=\"kw-alerte\">arrêt cardiaque</span></li><li><span class='kw-etio'>SEIPA</span> forme aiguë : <span class='kw-clinique'>vomissements en jet répétés incoercibles</span>, pâleur, léthargie, <span class=\"kw-clinique\">déshydratation</span> (<span class='kw-chiffre'><span class=\"kw-chiffre\">1-4h</span></span> après ingestion)</li><li><span class=\"kw-ci\">Allergie</span> alimentaire associée à un <span class='kw-alerte'>asthme persistant modéré à sévère non contrôlé</span> (sur-risque de réaction sévère)</li><li><span class='kw-clinique'>Cassure staturo-pondérale</span> / retard de croissance (formes digestives chroniques non <span class=\"kw-chiffre\">IgE</span>-médiées)</li></ul>","principes":"<p>Traitement symptomatique + éviction de l'allergène + <span class=\"kw-def\">éducation thérapeutique</span> ; l'<span class='kw-ttt'>immunothérapie allergénique</span> est le seul traitement curatif.</p><p><strong>Traitement symptomatique selon la manifestation</strong></p><ul><li><span class='kw-ttt'>Anti-histaminiques H1</span> (2nde génération) : rhinite, conjonctivite, <span class=\"kw-clinique\">prurit</span> ; voie orale ou locale</li><li>Rhinite persistante / obstruction → <span class='kw-ttt'><span class=\"kw-ttt\">corticoïdes</span> nasaux</span> ; conjonctivite → lavage + anti-allergiques locaux</li><li><span class=\"kw-clinique\">Dermatite</span> <span class=\"kw-etio\">atopique</span> : <span class='kw-ttt'>émollients</span> quotidiens + <span class='kw-ttt'>dermocorticoïdes</span> sur <span class=\"kw-clinique\">les</span> poussées</li><li><span class=\"kw-ttt\">Corticoïdes</span> par voie systémique = traitement d'<span class=\"kw-alerte\">urgence</span>, <span class=\"kw-ci\">à éviter</span> au long cours</li></ul><p><strong>Éviction allergénique (<span class=\"kw-def\">prévention secondaire</span>)</strong></p><ul><li>Acariens : <span class='kw-ttt'>housses anti-acariens</span>, lavage des draps <span class='kw-chiffre'><span class=\"kw-chiffre\">≥ 60°C</span></span>, humidité <span class='kw-chiffre'>&lt;<span class=\"kw-chiffre\"> 50%</span></span>, T° <span class='kw-chiffre'>&lt;<span class=\"kw-chiffre\"> 20°C</span></span>, aspiration avec filtre HEPA</li><li>Animaux hors de la chambre (<span class=\"kw-clinique\">les</span> allergènes de chat persistent plusieurs mois dans l'habitat)</li><li>Aliments : régime d'éviction + éducation à la lecture des étiquetages</li></ul><p><strong>Trousse d'<span class=\"kw-alerte\">urgence</span> + <span class=\"kw-ttt\">adrénaline</span> auto-injectable</strong></p><p>Indications absolues</p><ul><li>ATCD d'<span class='kw-alerte'><span class=\"kw-alerte\">anaphylaxie</span></span> (aliment, piqûre d'insecte, latex, effort, idiopathique)</li><li><span class=\"kw-ci\">Allergie</span> alimentaire + <span class='kw-alerte'>asthme persistant modéré à sévère non contrôlé</span></li><li>Mastocytose systémique (selon critères adulte/enfant)</li><li><span class=\"kw-ci\">Allergie</span> aux hyménoptères : enfant avec réaction systémique ; adulte sans ITA</li></ul><p><strong>Immunothérapie allergénique (ITA)</strong></p><p>Seul traitement curatif modifiant l'histoire naturelle de l'<span class=\"kw-ci\">allergie</span></p><ul><li>Doses croissantes d'allergène, durée <span class='kw-chiffre'><span class=\"kw-chiffre\">3-5 ans</span></span> ; pneumallergènes à partir de <span class='kw-chiffre'><span class=\"kw-chiffre\">5 ans</span></span></li><li>Hyménoptères : voie SC, débutée en rush hospitalier, si réaction systémique</li><li><span class='kw-ci'>CI absolues</span> : <span class=\"kw-ci\">grossesse</span> (initiation), néoplasie, MAI systémique, immunodépression sévère, asthme non contrôlé (transitoire)</li><li>La polysensibilisation n'est <span class='kw-ci'>pas</span> une <span class=\"kw-ci\">contre-indication</span></li></ul><p><strong>CAT accident <span class=\"kw-etio\">allergique</span> au venin d'hyménoptère</strong></p><ul><li>Piqûre d'abeille : <span class='kw-ttt'>retirer le dard</span> le plus tôt possible</li><li>Réaction locale bénigne : refroidir (glace) ± <span class='kw-ttt'>anti-histaminique oral</span></li><li>Réaction locale étendue : <span class='kw-ttt'>anti-H1 oral + <span class=\"kw-ttt\">corticoïdes</span> oraux</span> pendant <span class='kw-chiffre'><span class=\"kw-chiffre\">3-4 jours</span></span></li><li>Réaction systémique : <span class='kw-ttt'><span class=\"kw-ttt\">adrénaline</span> IM</span> + <span class=\"kw-def\">surveillance</span> hospitalière</li></ul><p><strong>APLV du nourrisson — alimentation lactée</strong></p><ul><li><span class=\"kw-chiffre\">1ère intention</span> : <span class='kw-ttt'>hydrolysat poussé de PLV</span> ; alternative : protéines de riz hydrolysées</li><li>Formule d'<span class='kw-ttt'>acides aminés</span> si <span class=\"kw-alerte\">anaphylaxie</span>, SEIPA forme aiguë sévère, symptômes sous <span class=\"kw-ci\">allaitement</span>, cassure staturo-pondérale</li><li>Éviction de tout produit laitier animal (chèvre/brebis inclus) ; viandes de bœuf/veau autorisées</li><li><span class=\"kw-ci\">Allaitement</span> maternel : poursuivre de façon exclusive jusqu'à la diversification</li></ul>","suivi":"<p><strong>Tolérance :</strong> décroissance des <span class='kw-bio'>IgE spécifiques</span> = acquisition d'une tolérance (<span class=\"kw-def\">suivi</span> des allergies alimentaires)<br><strong>Confirmation :</strong> <span class='kw-ttt'>test de provocation</span> pour confirmer la tolérance (<span class='kw-etio'>APLV</span>, <span class=\"kw-ci\">allergie</span> à l'œuf)<br><strong>ITA :</strong> efficacité à prouver dès la <span class='kw-chiffre'>1ère année</span>, sinon elle doit être interrompue<br><strong>Sécurité des tests :</strong> <span class=\"kw-def\">surveillance</span> <span class='kw-chiffre'><span class=\"kw-chiffre\">≥ 30 min</span></span> après prick-tests, <span class='kw-chiffre'><span class=\"kw-chiffre\">2-4h</span></span> après tests interventionnels<br><strong>École & déclaration :</strong> <span class='kw-def'>PAI</span> chez l'enfant ; déclarer <span class=\"kw-clinique\">les</span> allergies médicamenteuses à la pharmacovigilance</p>"},"liensGlobaux":[{"href":"https://cep-1f48c.kxcdn.com/wp-content/uploads/2023/07/ITEM_186_HYPERSENSIBILITE_2023.pdf","label":"Collège CEP — Hypersensibilité (PDF item 186)"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Suspicion d'hypersensibilité — Quel profil des symptômes à l'interrogatoire ?","detail":"<h4>CAT — Démarche diagnostique d'une <span class=\"kw-ci\">allergie</span> — Diagnostic = association exposition ↔ symptômes (interrogatoire) + objectivation d'une sensibilisation</h4>","branches":[{"to":"q-allergen","label":"Aigu &lt; 1h, non dose-dépendant, reproductible (IgE-médié)","color":"blue"},{"to":"q-nature","label":"Retardé (heures-jours), chronique, reproductible (non-IgE médié)","color":"amber"},{"to":"t-intolerance","label":"Délai variable, DOSE-dépendant, non reproductible","color":"green"}]},{"id":"q-allergen","kind":"decision","label":"Profil IgE-médié — quel allergène en cause ? — Tests cutanés en 1ère intention","branches":[{"to":"t-prick","label":"Aéroallergène ou aliment","color":"blue"},{"to":"t-idr","label":"Médicament injectable ou venin d'hyménoptère","color":"blue"}]},{"id":"t-prick","kind":"terminal","label":"Prick-tests (1ère intention)","color":"blue","detail":"<h4>Conduite</h4><ul><li><span class='s-med'>Prick-tests</span> en <span class='s-nb'><span class=\"kw-chiffre\">1ère intention</span></span> (méthode de référence de la sensibilisation <span class=\"kw-chiffre\">IgE</span>) — réalisables à <span class='s-nb'>tout âge</span></li><li>Lecture à <span class='s-nb'><span class=\"kw-chiffre\">15 min</span></span> ; positif si <span class=\"kw-clinique\">papule</span> <span class='s-nb'><span class=\"kw-chiffre\">≥ 3 mm</span></span> par rapport au témoin négatif</li><li>Témoin <span class='s-bio'>positif</span> (histamine/<span class=\"kw-ttt\">codéine</span>) + témoin <span class='s-bio'>négatif</span> (sérum physiologique) ; arrêt des anti-<span class=\"kw-chiffre\">H1</span> et <span class=\"kw-ttt\">dermocorticoïdes</span> <span class='s-nb'><span class=\"kw-chiffre\">7 jours</span></span> avant</li></ul><h4>Si prick négatif malgré une anamnèse évocatrice</h4><ul><li><span class='s-bio'>Dosage des <span class=\"kw-chiffre\">IgE</span> spécifiques</span> plasmatiques en <span class='s-nb'>2nde intention</span> (moins sensible que <span class=\"kw-clinique\">les</span> prick-tests)</li><li>Doute persistant → <span class='s-med'>test de provocation</span> (gold standard, double aveugle, milieu hospitalier spécialisé)</li></ul><h4>Renvoi</h4><ul><li>Item 188 (Asthme, rhinite <span class=\"kw-etio\">allergique</span>)</li></ul>"},{"id":"t-idr","kind":"terminal","label":"IDR à lecture immédiate","color":"blue","detail":"<h4>Conduite</h4><ul><li><span class='s-med'><span class=\"kw-clinique\">IDR</span> à lecture immédiate</span> (lecture à <span class='s-nb'><span class=\"kw-chiffre\">20 min</span></span>) pour <span class=\"kw-clinique\">les</span> <span class='s-etio'>médicaments injectables</span> et les <span class='s-etio'>venins d'hyménoptères</span></li><li><span class='s-bio'>Dosage des <span class=\"kw-chiffre\">IgE</span> spécifiques</span> en <span class=\"kw-bio\">complément</span></li><li>Si tests négatifs (ex. antibiotiques) → <span class='s-med'>test de provocation</span> en milieu hospitalier</li></ul><h4>Si <span class=\"kw-alerte\">anaphylaxie</span> au venin</h4><ul><li>Recherche d'une <span class='s-etio'>mastocytose</span> indispensable</li><li><span class='s-med'>Immunothérapie allergénique</span> si réaction systémique de mécanisme <span class=\"kw-etio\">allergique</span> démontré</li></ul>"},{"id":"q-nature","kind":"decision","label":"Profil non-IgE médié — quelle atteinte ? — Mécanisme médié par les LT, symptômes retardés","branches":[{"to":"t-patch","label":"Eczéma de contact / toxidermie médicamenteuse","color":"blue"},{"to":"t-eviction","label":"Allergie alimentaire non IgE-médiée","color":"amber"}]},{"id":"t-patch","kind":"terminal","label":"Patch-tests (épicutanés)","color":"blue","detail":"<h4>Conduite</h4><ul><li><span class='s-med'>Patch-tests</span> : toxidermies retardées et <span class='s-etio'><span class=\"kw-clinique\">eczéma</span> de <span class=\"kw-def\">contact</span></span> — à distance de la <span class=\"kw-clinique\">poussée</span> (<span class='s-nb'><span class=\"kw-chiffre\">1 mois</span></span>)</li><li>Lecture à <span class='s-nb'><span class=\"kw-chiffre\">48h</span></span> puis <span class='s-nb'><span class=\"kw-chiffre\">J3</span>-J4</span> ; positif si reproduction de l'<span class=\"kw-clinique\">eczéma</span></li><li>± <span class='s-med'><span class=\"kw-clinique\">IDR</span> à lecture retardée</span> (<span class='s-nb'><span class=\"kw-chiffre\">24-48h</span></span>) pour <span class=\"kw-clinique\">les</span> toxidermies médicamenteuses</li></ul><h4>Pièges</h4><ul><li>Patch-tests <span class='s-ci'>non recommandés</span> pour explorer <span class=\"kw-clinique\">les</span> allergies alimentaires retardées</li><li><span class='s-ci'>CI</span> : toxidermies graves, <span class=\"kw-ttt\">corticoïdes</span> ou <span class=\"kw-ttt\">immunosuppresseurs</span> (bloquent la réaction)</li></ul><h4>Renvoi</h4><ul><li>Item 187 (<span class=\"kw-clinique\">Eczéma</span> de <span class=\"kw-def\">contact</span>, dermatite <span class=\"kw-etio\">atopique</span>)</li><li>Items 115 / 325 (Toxidermies)</li></ul>"},{"id":"t-eviction","kind":"terminal","label":"Épreuve d'éviction-réintroduction","color":"amber","detail":"<h4>Conduite</h4><ul><li><span class='s-med'>Éviction</span> de <span class='s-nb'><span class=\"kw-chiffre\">2 à 4 semaines</span></span> de l'aliment suspect, puis réintroduction</li><li>Aucun test <span class=\"kw-ttt\">biologique</span> utile dans <span class=\"kw-clinique\">les</span> formes non <span class=\"kw-chiffre\">IgE</span>-médiées</li><li>Amélioration à l'éviction + rechute à la réintroduction → responsabilité de l'aliment confirmée</li></ul>"},{"id":"t-intolerance","kind":"terminal","label":"Hypersensibilité non allergique (intolérance)","color":"green","detail":"<h4>Conduite</h4><ul><li>Profil d'<span class='s-etio'>histaminolibération</span> non spécifique, <span class='s-clin'>dose-dépendante</span> (pas de symptôme sous une dose-seuil)</li><li>Pas de tests allergologiques (prick-tests / <span class=\"kw-chiffre\">IgE</span> inutiles)</li><li>Éviction adaptée à la dose ; aliments et médicaments histaminolibérateurs (charcuterie, fromages fermentés, <span class=\"kw-ttt\">AINS</span>, curares, produits de contraste iodés)</li></ul>"}]},"cards":[{"i":"1b0cf7c17357","n":186,"o":"186-11","u":"Étiologies","t":"Connaître le rôle de l’environnement extérieur, domestique et professionnel dans l’allergie","q":"Quels sont les autres allergènes importants et les facteurs environnementaux modulant le risque allergique ?","a":"Les autres allergènes importants incluent :\n<ul>\n  <li>Les <strong>venins d'hyménoptères</strong> (abeille, guêpe, frelon) : plus fréquents chez l'adulte.</li>\n  <li>Les <strong>médicaments</strong> : &beta;-lactamines, AINS, curares, bleu patenté.</li>\n  <li>Le <strong>latex</strong> : associé au syndrome latex-fruits exotiques.</li>\n  <li>Les <strong>allergènes de contact</strong> : nickel, parfums, conservateurs cosmétiques, chromates, responsables d'eczéma de contact.</li>\n</ul>\nLes facteurs environnementaux modulant le risque allergique sont :\n<ul>\n  <li>Le <strong>tabagisme</strong> (passif pré- et post-natal) : augmente le risque atopique.</li>\n  <li>La <strong>pollution atmosphérique</strong> (particules fines, ozone, NO₂) : potentialise l'effet des pollens.</li>\n  <li>La <strong>théorie hygiéniste</strong> et la baisse de la biodiversité microbienne (dû à la baisse des contacts infectieux dans l'enfance) : corrélées à l'augmentation des maladies allergiques.</li>\n  <li>Les <strong>facteurs protecteurs</strong> : enfants les plus jeunes d'une fratrie, vie en crèche (contage infectieux précoce), milieu rural avec endotoxines bactériennes (« effet ferme »).</li>\n</ul>"},{"i":"70af0f5f4401","n":186,"o":"186-11","u":"Étiologies","t":"Connaître le rôle de l’environnement extérieur, domestique et professionnel dans l’allergie","q":"Quels sont les principaux allergènes professionnels et les métiers à risque d'asthme professionnel ?","a":"Les principaux allergènes professionnels et les métiers à risque d'asthme professionnel sont :\n<ul>\n  <li><strong>Boulanger / pâtissier</strong> : <strong>farines de céréales</strong>, enzymes (&alpha;-amylases).</li>\n  <li><strong>Personnel de santé</strong> : <strong>latex</strong>, glutaraldéhyde, désinfectants.</li>\n  <li><strong>Coiffeur</strong> : persulfates, paraphénylènediamine.</li>\n  <li><strong>Peintres / industrie automobile</strong> : <strong>isocyanates</strong> (TDI, MDI, HDI).</li>\n  <li><strong>Travailleurs du bois</strong> : poussières de bois (chêne, hêtre, exotiques).</li>\n  <li><strong>Agriculteurs / éleveurs</strong> : foin moisi (actinomycètes), protéines aviaires.</li>\n</ul>"},{"i":"8c0fa21b9ba2","n":186,"o":"186-11","u":"Étiologies","t":"Connaître le rôle de l’environnement extérieur, domestique et professionnel dans l’allergie","q":"Quelles sont les principales familles de pollens responsables d'allergies saisonnières et leurs périodes d'émission habituelles ?","a":"Les principales familles de pollens responsables d'allergies saisonnières sont :\n<ul>\n  <li>Les <strong>arbres</strong> (Betulacées comme le bouleau, aulne, charme, noisetier ; et cyprès dans le sud de la France) : période d'émission début de printemps (<strong>mars-avril</strong>).</li>\n  <li>Les <strong>graminées</strong> : très ubiquitaires, période d'émission fin du printemps / début de l'été (<strong>mai-juillet</strong>).</li>\n  <li>Les <strong>herbacées</strong> (armoise, ambroisie) : période d'émission printemps et été (<strong>avril-septembre</strong>).</li>\n</ul>"},{"i":"be4872aba63d","n":186,"o":"186-11","u":"Étiologies","t":"Connaître le rôle de l’environnement extérieur, domestique et professionnel dans l’allergie","q":"Quels sont les principaux pneumallergènes domestiques perannuels et leurs conditions de prolifération ?","a":"Les principaux pneumallergènes domestiques perannuels sont :\n<ul>\n  <li>Les <strong>acariens</strong> (<i>Dermatophagoides pteronyssinus</i>, <i>D. farinae</i>) : on les trouve dans les poussières de maison, la literie, les tapis, les moquettes, les peluches et les canapés. Ils prolifèrent à une température de <strong>20–25 °C</strong> et une forte <strong>humidité</strong>.</li>\n  <li>Les <strong>phanères d'animaux</strong> (chien, chat, rongeurs) : les squames, la salive et l'urine en sont la source. Les allergènes de chat peuvent persister plusieurs mois après le départ de l'animal.</li>\n  <li>Les <strong>blattes</strong> (cafards) : elles sont présentes dans les cuisines, salles de bain et lieux aux conditions d'hygiène défavorables.</li>\n  <li>Les <strong>moisissures intérieures</strong> (<i>Aspergillus</i>, <i>Penicillium</i>) : elles se développent dans les pièces humides (salle de bain, cuisine, caves). Une autre moisissure, <i>Alternaria</i>, est une moisissure d'extérieur marquant une gravité asthmatique chez l'enfant.</li>\n</ul>"},{"i":"0714d5d2be03","n":186,"o":"186-14","u":"Suivi et/ou pronostic","t":"Connaître les principes de l’éducation thérapeutique dans l’allergie alimentaire (PAI, indication de l’adrénaline auto-injectable...)","q":"Quels sont les différents composants de la trousse d'urgence pour une allergie alimentaire, et quand l'adrénaline auto-injectable est-elle indiquée ?","a":"<p>La trousse d'urgence en cas d'allergie alimentaire comprend :</p><ul><li>Un <strong>stylo d'adrénaline auto-injectable</strong> (si histoire ou risque d'anaphylaxie).</li><li>Des <strong>antihistaminiques H1 oraux</strong>.</li><li>Des <strong>corticoïdes oraux</strong>.</li><li>Des <strong>bronchodilatateurs β2-mimétiques</strong> si antécédent de bronchospasme.</li></ul><p>L'adrénaline auto-injectable est indiquée en cas d'anaphylaxie ou de risque élevé d'anaphylaxie, notamment chez les patients ayant déjà présenté une réaction anaphylactique sévère.</p>"},{"i":"1d21f2118360","n":186,"o":"186-14","u":"Suivi et/ou pronostic","t":"Connaître les principes de l’éducation thérapeutique dans l’allergie alimentaire (PAI, indication de l’adrénaline auto-injectable...)","q":"Quelles sont les indications absolues d'une trousse d'urgence avec adrénaline auto-injectable dans la gestion des allergies ?","a":"<p>Une trousse d'urgence contenant de l'adrénaline auto-injectable est absolument indiquée dans les situations suivantes :</p><ul><li><strong>Anaphylaxie antérieure</strong> à un aliment, une piqûre d'insecte, le latex, induite par l'effort physique, ou idiopathique.</li><li><strong>Allergie alimentaire + asthme persistant modéré à sévère non contrôlé</strong> chez la même personne.</li><li><strong>Mastocytose systémique</strong> (chez l'adulte avec antécédent de réaction systémique, ou chez l'enfant si atteinte cutanée &gt; 50 % de la surface corporelle, une tryptasémie basale &gt; 20 ng/mL, ou des bulles dans les 3 premières années de vie).</li><li>Allergie aux hyménoptères chez l'enfant ayant provoqué une <strong>réaction systémique plus sévère que cutanéo-muqueuse</strong>.</li><li>Allergie aux hyménoptères chez l'adulte ayant provoqué une <strong>réaction systémique non éligible à une immunothérapie spécifique</strong> (ITA).</li></ul>"},{"i":"2d84bec2cac2","n":186,"o":"186-14","u":"Suivi et/ou pronostic","t":"Connaître les principes de l’éducation thérapeutique dans l’allergie alimentaire (PAI, indication de l’adrénaline auto-injectable...)","q":"Qu'est-ce que le Projet d'Accueil Individualisé (PAI) dans le contexte de l'allergie alimentaire chez l'enfant ?","a":"<p>Le <strong>Projet d'Accueil Individualisé (PAI)</strong> est un document écrit pivot chez l'enfant scolarisé, établi à la demande des parents. Il permet une <strong>dérogation au secret médical</strong> pour définir un protocole de soins en cas de réaction allergique accidentelle. Il précise :</p><ul><li>Les <strong>aliments à éviter</strong>, notamment à la cantine.</li><li>La <strong>trousse d'urgence</strong> à disposition.</li><li>Le protocole d'<strong>injection d'adrénaline</strong> si nécessaire.</li></ul>"},{"i":"2ea019abd28d","n":186,"o":"186-14","u":"Suivi et/ou pronostic","t":"Connaître les principes de l’éducation thérapeutique dans l’allergie alimentaire (PAI, indication de l’adrénaline auto-injectable...)","q":"Quelle est la posologie et le mode d'administration de l'adrénaline auto-injectable, et quelles précautions doivent être prises après son administration ?","a":"<p>L'adrénaline auto-injectable est administrée par <strong>voie intramusculaire (IM)</strong> exclusivement, dans la <strong>face antéro-latérale de la cuisse</strong>. Elle peut être injectée à travers les vêtements.</p><p>Les posologies sont :</p><ul><li><strong>Adulte : 0,3 mg</strong> (stylo &gt; 300 µg).</li><li><strong>Enfant (15-30 kg) : 0,15 mg</strong> (stylo &gt; 150 µg).</li></ul><p>Après l'injection, il faut :</p><ul><li><strong>Appeler systématiquement le 15</strong>.</li><li>Placer le patient en <strong>position allongée, jambes surélevées</strong>, sauf en cas de dyspnée (position semi-assise).</li><li>L'injection peut être <strong>renouvelée toutes les 5 à 15 minutes</strong> si les symptômes persistent ou réapparaissent.</li></ul>"},{"i":"b354d6cc6f26","n":186,"o":"186-14","u":"Suivi et/ou pronostic","t":"Connaître les principes de l’éducation thérapeutique dans l’allergie alimentaire (PAI, indication de l’adrénaline auto-injectable...)","q":"Comment interpréter la classification de Ring & Messmer pour décider de l'administration d'adrénaline en cas d'anaphylaxie ?","a":"<p>La classification de Ring & Messmer stratifie la sévérité de l'anaphylaxie :</p><ul><li><strong>Grade I</strong> : Manifestations <strong>cutanéo-muqueuses isolées</strong> (érythème, urticaire, prurit, angio-œdème localisé sans signe muqueux pharyngé). L'adrénaline n'est pas indiquée.</li><li><strong>Grade II</strong> : Atteinte <strong>multiviscérale modérée</strong> (hypotension modérée, tachycardie, dyspnée, toux, troubles digestifs). L'<strong>adrénaline IM</strong> est indiquée, avec remplissage et appel du 15.</li><li><strong>Grade III</strong> : Atteinte <strong>multiviscérale sévère</strong> menaçant la vie (collapsus, tachycardie/bradycardie, troubles du rythme, bronchospasme sévère). L'<strong>adrénaline IM</strong> (voire IV titrée) est indiquée, avec remplissage massif, oxygène et appel du 15.</li><li><strong>Grade IV</strong> : <strong>Arrêt cardio-respiratoire</strong>. La <strong>réanimation cardio-pulmonaire (RCP)</strong> et l'adrénaline IV bolus selon protocole ACLS sont impératifs, avec appel du 15.</li></ul><p>Toute réaction de <strong>Grade II et plus</strong> impose l'injection immédiate d'<strong>adrénaline IM</strong>, sans attendre la confirmation clinique.</p>"},{"i":"b7a082a7465f","n":186,"o":"186-14","u":"Suivi et/ou pronostic","t":"Connaître les principes de l’éducation thérapeutique dans l’allergie alimentaire (PAI, indication de l’adrénaline auto-injectable...)","q":"Quels sont les objectifs de l'éducation thérapeutique dans la prise en charge de l'allergie alimentaire ?","a":"<p>L'éducation thérapeutique dans l'allergie alimentaire vise principalement deux objectifs :</p><ul><li>Prévenir l'<strong>exposition accidentelle</strong> à l'allergène (éviction, lecture d'étiquettes).</li><li>Savoir <strong>réagir en urgence</strong> en cas de réaction (plan d'action, trousse d'urgence, adrénaline auto-injectable).</li></ul>"},{"i":"34826340a98a","n":186,"o":"186-15","u":"Diagnostic positif","t":"Connaître les modalités de diagnostic d’une conjonctivite allergique","q":"Quels sont les signes cliniques cardinaux et fortement évocateurs d'une conjonctivite allergique ?","a":"<ul><li>Le <strong>prurit oculaire</strong> est le symptôme cardinal, souvent intolérable, et un signe d'orientation majeur, quasi pathognomonique.</li><li>Le <strong>larmoiement</strong>, clair et non purulent.</li><li>L'<strong>hyperhémie conjonctivale</strong> diffuse, bilatérale et symétrique.</li><li>Le <strong>chémosis</strong> (œdème conjonctival translucide) et l'<strong>œdème palpébral</strong>.</li><li>La <strong>photophobie</strong>, fréquente en phase aiguë.</li></ul>"},{"i":"bc45f7007bcb","n":186,"o":"186-15","u":"Diagnostic positif","t":"Connaître les modalités de diagnostic d’une conjonctivite allergique","q":"Quelle est la démarche diagnostique essentielle devant une suspicion de conjonctivite allergique ?","a":"<ul><li>L'<strong>anamnèse</strong> est cruciale, recherchant le caractère bilatéral, le contexte saisonnier ou perannuel, l'association à une rhinite, et les antécédents personnels et familiaux d'atopie. Le <strong>prurit cardinal</strong> est le signe le plus évocateur.</li><li>L'<strong>examen clinique</strong> confirme l'absence de sécrétions purulentes ou d'atteinte cornéenne sévère.</li><li>Les <strong>tests cutanés (prick-tests)</strong> aux pneumallergènes sont essentiels pour identifier l'allergène.</li><li>Les <strong>IgE spécifiques</strong> sont une alternative si les tests cutanés sont contre-indiqués ou discordants.</li></ul>"},{"i":"d760cf7c43e1","n":186,"o":"186-15","u":"Diagnostic positif","t":"Connaître les modalités de diagnostic d’une conjonctivite allergique","q":"Quelle est la définition et la physiopathologie principale de la conjonctivite allergique ?","a":"<p>La conjonctivite allergique est l'expression oculaire d'une <strong>hypersensibilité immédiate de Type I (IgE-médiée)</strong>. Elle est le plus souvent bilatérale et associée à une rhinite allergique sur un terrain atopique.</p>"},{"i":"fb21158003f6","n":186,"o":"186-15","u":"Diagnostic positif","t":"Connaître les modalités de diagnostic d’une conjonctivite allergique","q":"Quels sont les principaux diagnostics différentiels à éliminer devant une conjonctivite allergique ?","a":"<ul><li>La <strong>conjonctivite infectieuse bactérienne</strong>, caractérisée par des <strong>sécrétions purulentes</strong> et souvent unilatérale.</li><li>La <strong>conjonctivite virale</strong>, associée à une <strong>adénopathie pré-auriculaire</strong> et un contexte épidémique.</li><li>La <strong>kérato-conjonctivite vernale</strong>, spécifique à l'enfant (garçon), avec <strong>papilles géantes</strong> et <strong>atteinte cornéenne marquée</strong>.</li><li>Le <strong>syndrome sec</strong>, avec une sensation de brûlure plutôt que de prurit, et un test de Schirmer pathologique.</li><li>La <strong>conjonctivite irritative</strong>, liée à un contact chimique ou des polluants.</li></ul>"},{"i":"2e4722be7b65","n":186,"o":"186-16","u":"Prise en charge","t":"Connaître les principes du traitement d’une conjonctivite allergique","q":"Dans quelles situations les corticoïdes locaux oculaires sont-ils indiqués pour une conjonctivite allergique et quelles précautions doivent être prises ?","a":"<p>Les collyres corticoïdes ne sont prescrits qu'en cas de <strong>certitude diagnostique</strong> et <strong>après échec des traitements précédents</strong>.</p><p>Un <strong>avis ophtalmologique est obligatoire</strong> en raison des risques de <strong>glaucome cortisonique</strong>, de <strong>cataracte</strong> et d'<strong>infection oculaire</strong>.</p>"},{"i":"35192dd7798e","n":186,"o":"186-16","u":"Prise en charge","t":"Connaître les principes du traitement d’une conjonctivite allergique","q":"Quels sont les traitements symptomatiques médicamenteux de première et deuxième intention pour la conjonctivite allergique ?","a":"<ul><li><strong>Antihistaminiques locaux</strong> (collyres) : <strong>lévocabastine</strong>, <strong>olopatadine</strong> (double action antiH1 + stabilisateur mastocytaire), <strong>azélastine</strong>. Ils sont en première intention pour les formes isolées.</li><li><strong>Cromones locales</strong> (collyres) : <strong>cromoglycate de sodium</strong>. Ce sont des stabilisateurs mastocytaires, utiles en prévention avant exposition saisonnière.</li><li><strong>Antihistaminiques oraux</strong> : <strong>antiH1 de 2<sup>e</sup> génération</strong> (cétirizine, loratadine, etc.), indiqués en cas de <strong>rhino-conjonctivite</strong> pour une action systémique.</li></ul>"},{"i":"638617deb6a8","n":186,"o":"186-16","u":"Prise en charge","t":"Connaître les principes du traitement d’une conjonctivite allergique","q":"Quels sont les trois niveaux de traitement de la conjonctivite allergique mentionnés dans la stratégie thérapeutique ?","a":"<p>Le traitement de la conjonctivite allergique repose sur trois niveaux :</p><ul><li>Niveau 1 : <strong>éviction allergénique</strong> et <strong>lavage oculaire</strong>.</li><li>Niveau 2 : <strong>Traitement symptomatique</strong> (antihistaminiques locaux ou oraux, cromones).</li><li>Niveau 3 : <strong>Traitement étiologique</strong> par immunothérapie allergénique (ITA).</li></ul>"},{"i":"e3ae4c5404c5","n":186,"o":"186-16","u":"Prise en charge","t":"Connaître les principes du traitement d’une conjonctivite allergique","q":"Quand l'immunothérapie allergénique (ITA) est-elle indiquée pour une rhino-conjonctivite allergique et quels en sont les bénéfices ?","a":"<p>L'ITA est indiquée pour la <strong>rhino-conjonctivite saisonnière</strong> persistante <strong>modérée à sévère</strong>, malgré un traitement bien conduit par <strong>antihistaminiques H1</strong> et <strong>corticoïdes nasaux</strong>.</p><p>Ses bénéfices sont :</p><ul><li>Réduction des symptômes.</li><li>Diminution de la consommation médicamenteuse.</li><li>Prévention de l'apparition de l'<strong>asthme</strong> (seul traitement modifiant l'histoire naturelle de l'allergie).</li></ul>"},{"i":"fc424f77873c","n":186,"o":"186-16","u":"Prise en charge","t":"Connaître les principes du traitement d’une conjonctivite allergique","q":"Quelles sont les mesures d'éviction allergénique spécifiques en cas de conjonctivite allergique et les modalités du lavage oculaire ?","a":"<ul><li><strong>Acariens</strong> : housses anti-acariens, lavage des draps à <strong>≥ 60 °C</strong>, aspiration HEPA.</li><li><strong>Pollens</strong> : sécher le linge à l'intérieur, fermer les fenêtres en période de pic pollinique.</li><li><strong>Animaux</strong> : ne pas les laisser accéder à la chambre, lavage régulier.</li><li>Le <strong>lavage oculaire</strong> se fait au <strong>sérum physiologique</strong>, plusieurs fois par jour pendant la phase symptomatique pour éliminer mécaniquement l'allergène et les médiateurs locaux.</li></ul>"},{"i":"088457ade197","n":186,"o":"186-17","u":"Pédiatrie — Epidémiologie","t":"Connaître les grandes tendances épidémiologiques de l’allergie alimentaire : prévalence, mortalité, allergènes","q":"Quels sont les principaux allergènes alimentaires pédiatriques classés par tranche d'âge ?","a":"<ul><li><strong>Avant 6 mois</strong> : Le <strong>lait de vache</strong> (APLV), avec la caséine, l'α-lactalbumine et la β-lactoglobuline comme principaux allergènes.</li><li><strong>5 à 15 mois</strong> : L'<strong>œuf</strong> (premier allergène), l'<strong>arachide</strong>, le lait de vache, la moutarde et la morue. L'ovalbumine est thermolabile, l'ovomucoïde est thermorésistant.</li><li><strong>Après 1 an</strong> : L'<strong>arachide</strong> devient le premier allergène alimentaire.</li><li><strong>Après 3 ans</strong> : L'arachide, les fruits à coque, les poissons, les crustacés et le kiwi.</li></ul>"},{"i":"126d10768bf2","n":186,"o":"186-17","u":"Pédiatrie — Epidémiologie","t":"Connaître les grandes tendances épidémiologiques de l’allergie alimentaire : prévalence, mortalité, allergènes","q":"Quelle est la prévalence de l'allergie alimentaire pédiatrique en France et à quel âge atteint-elle son pic ?","a":"<p>L'allergie alimentaire pédiatrique concerne <strong>5 à 7 %</strong> des enfants français. Le pic de prévalence est observé entre <strong>6 et 10 ans</strong>, atteignant <strong>7 %</strong>.</p>"},{"i":"21f86a789203","n":186,"o":"186-17","u":"Pédiatrie — Epidémiologie","t":"Connaître les grandes tendances épidémiologiques de l’allergie alimentaire : prévalence, mortalité, allergènes","q":"Quels allergènes sont associés à une allergie alimentaire durable et lesquels sont majoritairement transitoires chez l'enfant ?","a":"<ul><li><strong>Allergies transitoires</strong> : Le <strong>lait de vache</strong> (guérison d'environ 80 % avant 3 ans) et l'<strong>œuf</strong> (guérison d'environ 80 % avant 5 ans).</li><li><strong>Allergies persistantes</strong> : L'<strong>arachide</strong> (environ 80 % de persistance à vie), les <strong>fruits à coque</strong> (environ 80 % de persistance), les <strong>poissons</strong> et les <strong>crustacés</strong> (persistance le plus souvent).</li></ul>"},{"i":"a06a5125a6fd","n":186,"o":"186-17","u":"Pédiatrie — Epidémiologie","t":"Connaître les grandes tendances épidémiologiques de l’allergie alimentaire : prévalence, mortalité, allergènes","q":"Quel est l'allergène le plus mortel en cas de décès anaphylactique chez l'enfant ?","a":"<p>L'allergène le plus mortel en cas de décès anaphylactique chez l'enfant est l'<strong>arachide</strong> et les <strong>fruits à coque</strong>.</p>"},{"i":"cada2c1561c2","n":186,"o":"186-17","u":"Pédiatrie — Epidémiologie","t":"Connaître les grandes tendances épidémiologiques de l’allergie alimentaire : prévalence, mortalité, allergènes","q":"Qu'est-ce que la \"marche atopique\" et quelles sont les étapes chronologiques des manifestations observées ?","a":"<p>La \"marche atopique\" est la succession des manifestations atopiques chez un enfant. Elle débute par la <strong>dermatite atopique</strong> (nourrisson), suivie par l'<strong>allergie alimentaire</strong>, puis l'<strong>asthme</strong> (vers 3-4 ans) et enfin la <strong>rhino-conjonctivite</strong> (à l'adolescence).</p>"},{"i":"35b23e4a290b","n":186,"o":"186-18","u":"Pédiatrie — Epidémiologie","t":"Connaître les grandes tendances épidémiologiques de l’allergie respiratoire : prévalence, mortalité, morbidité, allergènes","q":"Quels sont les facteurs de risque spécifiques de l'allergie respiratoire chez l'enfant ?","a":"<p>Les facteurs de risque comprennent :</p><ul><li><strong>Génétiques</strong> : polygénique, avec un risque augmentant si les parents sont asthmatiques (10% sans parent, 25% avec 1 parent, &gt; 50% avec 2 parents).</li><li><strong>Environnementaux</strong> : infections virales (favorisent l'hyperréactivité bronchique durable), tabagisme parental périnatal, pollution intérieure (parfums, produits ménagers), pollution atmosphérique et altération du microbiote.</li><li>L'<strong>effort</strong> : peut déclencher un bronchospasme chez &gt; 80% des enfants asthmatiques, surtout en air froid et sec.</li></ul>"},{"i":"4d10d3173788","n":186,"o":"186-18","u":"Pédiatrie — Epidémiologie","t":"Connaître les grandes tendances épidémiologiques de l’allergie respiratoire : prévalence, mortalité, morbidité, allergènes","q":"Quel est l'impact de l'asthme sur la mortalité et la morbidité pédiatriques en France ?","a":"<p>L'asthme est responsable d'environ <strong>1000 décès par an en France</strong>, considérés comme évitables. L'asthme aigu grave pédiatrique est surreprésenté en milieu socio-économique défavorisé. La morbidité se traduit par un <strong>absentéisme scolaire</strong>, un retentissement sur les performances et la qualité de vie familiale, ainsi que des <strong>hospitalisations répétées</strong>.</p>"},{"i":"8faa8e3b986f","n":186,"o":"186-18","u":"Pédiatrie — Epidémiologie","t":"Connaître les grandes tendances épidémiologiques de l’allergie respiratoire : prévalence, mortalité, morbidité, allergènes","q":"Qu'est-ce que la marche atopique et quelles sont ses étapes dans l'allergie respiratoire chez l'enfant ?","a":"<p>La marche atopique est une succession chronologique de manifestations allergiques chez l'enfant. Elle débute typiquement par la <strong>dermatite atopique</strong> (nourrisson, ≤ 1 an), suivie par les <strong>allergies alimentaires</strong> (nourrisson, 1-2 ans). L'<strong>asthme allergique</strong> émerge ensuite (vers <strong>3-4 ans</strong>), et enfin la <strong>rhino-conjonctivite allergique</strong> apparaît à l'adolescence.</p>"},{"i":"b7b9e72f2a03","n":186,"o":"186-18","u":"Pédiatrie — Epidémiologie","t":"Connaître les grandes tendances épidémiologiques de l’allergie respiratoire : prévalence, mortalité, morbidité, allergènes","q":"Quels sont les principaux allergènes respiratoires pédiatriques et leurs spécificités ?","a":"<p>Les principaux allergènes respiratoires pédiatriques sont :</p><ul><li>Les allergènes <strong>domestiques (perannuels)</strong> : <strong>acariens (les plus fréquents)</strong>, phanères d'animaux (chat, chien), moisissures (<em>Alternaria</em>, marqué comme facteur de gravité de l'asthme pédiatrique).</li><li>Les allergènes <strong>extérieurs (saisonniers)</strong> : pollens d'arbres (bouleau, cyprès), <strong>graminées</strong>, herbacées (armoise, ambroisie). Leur apparition est plus tardive, souvent post-puberté.</li><li>Les <strong>infections virales</strong> (Rhinovirus, VRS, SARS-CoV-2) qui sont des <strong>déclencheurs majeurs</strong> d'exacerbations asthmatiques.</li></ul>"},{"i":"b9fc38619074","n":186,"o":"186-18","u":"Pédiatrie — Epidémiologie","t":"Connaître les grandes tendances épidémiologiques de l’allergie respiratoire : prévalence, mortalité, morbidité, allergènes","q":"Quelle est la prévalence de l'allergie respiratoire infantile et sa tendance évolutive ?","a":"<p>L'allergie respiratoire est la <strong>maladie chronique la plus fréquente</strong> de l'enfant. Sa prévalence a <strong>doublé en 20 ans</strong> en raison de l'évolution environnementale. Environ <strong>11%</strong> des enfants sont atteints d'asthme allergique pédiatrique en France, et environ <strong>25%</strong> de rhinite allergique pédiatrique.</p>"},{"i":"38af3272b8f2","n":186,"o":"186-19","u":"Pédiatrie — Examens complémentaires","t":"Connaître l’indication de la réalisation d’un test de dépistage IgE multiallergénique (aéroallergènes et trophallergènes)","q":"Dans quel contexte pédiatrique les tests multi-allergéniques IgE (Phadiatop, Trophatop, Phadiatop Infant) sont-ils particulièrement indiqués ?","a":"<p>Ces tests sont particulièrement utiles en pédiatrie lorsque le prick-test est :</p><ul><li>Limité techniquement (chez le <strong>très jeune enfant</strong>).</li><li>Contre-indiqué (en cas d'<strong>eczéma sévère diffus</strong>, de <strong>dermographisme</strong>).</li><li>Non interprétable (si le patient prend des <strong>antihistaminiques non sevrables</strong>).</li></ul>"},{"i":"532c3228132b","n":186,"o":"186-19","u":"Pédiatrie — Examens complémentaires","t":"Connaître l’indication de la réalisation d’un test de dépistage IgE multiallergénique (aéroallergènes et trophallergènes)","q":"Quels sont les examens complémentaires à ne PAS prescrire pour le diagnostic d'allergie chez l'enfant ?","a":"<p>Il ne faut <strong>PAS</strong> prescrire les examens suivants :</p><ul><li>Les <strong>IgE totales sériques</strong> : inutiles et non remboursées.</li><li>Les <strong>polynucléaires éosinophiles</strong> : non recommandés pour le diagnostic d'allergie.</li><li>Les <strong>IgG spécifiques</strong> : aucune indication en allergologie pédiatrique courante.</li></ul>"},{"i":"6981444fac87","n":186,"o":"186-19","u":"Pédiatrie — Examens complémentaires","t":"Connaître l’indication de la réalisation d’un test de dépistage IgE multiallergénique (aéroallergènes et trophallergènes)","q":"Quelle est la hiérarchie des examens complémentaires pour le diagnostic d'allergie en pédiatrie ?","a":"<p>La hiérarchie diagnostique en pédiatrie est la suivante :</p><ul><li><strong>Anamnèse et examen clinique</strong> : toujours en première intention.</li><li><strong>Prick-tests</strong> : s'ils sont réalisables et sans contre-indication.</li><li><strong>Tests multi-allergéniques IgE</strong> (Phadiatop/Trophatop/Phadiatop Infant) : si les pricks sont contre-indiqués/impossibles, ou pour un dépistage atopique rapide.</li><li><strong>IgE spécifiques ciblées et recombinants</strong> : si le multi-allergénique est positif ou pour préciser une sensibilisation.</li><li><strong>Test de provocation orale (TPO)</strong> : en centre spécialisé, si le diagnostic est incertain ou pour évaluer la tolérance acquise.</li></ul>"},{"i":"7255ce800309","n":186,"o":"186-19","u":"Pédiatrie — Examens complémentaires","t":"Connaître l’indication de la réalisation d’un test de dépistage IgE multiallergénique (aéroallergènes et trophallergènes)","q":"Quel est l'intérêt du Phadiatop Infant spécifiquement en pédiatrie ?","a":"<p>Le <strong>Phadiatop Infant</strong> est le test de choix chez le <strong>nourrisson et le jeune enfant</strong> présentant des symptômes mixtes ou non spécifiques, combinant la détection d'<strong>aéroallergènes et de trophallergènes</strong>. Il permet un dépistage atopique rapide et constitue une alternative non invasive quand le prick-test est difficile à réaliser.</p>"},{"i":"6aac3e9c9606","n":186,"o":"186-6","u":"Diagnostic positif","t":"Connaître et hiérarchiser les différentes étapes du diagnostic des allergies respiratoires","q":"Quand réalise-t-on des tests cutanés (prick-tests) dans le diagnostic d'une allergie respiratoire et quels sont les critères positifs ?","a":"<p>Les tests cutanés (<strong>prick-tests</strong>) sont réalisés en <strong>1<sup>ère</sup> intention</strong> dans le diagnostic d'une allergie respiratoire, après l'anamnèse. Leur objectif est d'objectiver une <strong>sensibilisation IgE-médiée</strong>. Les critères positifs sont une <strong>papule ≥ 3 mm</strong> par rapport au témoin négatif, avec un témoin positif (histamine) réactif.</p>"},{"i":"7ae0b0e5d930","n":186,"o":"186-6","u":"Diagnostic positif","t":"Connaître et hiérarchiser les différentes étapes du diagnostic des allergies respiratoires","q":"Dans quelles situations les tests biologiques (IgE spécifiques) sont-ils indiqués pour le diagnostic d'une allergie respiratoire et quel est leur critère positif ?","a":"<p>Les tests biologiques (<strong>IgE spécifiques</strong>) sont indiqués en <strong>2<sup>nde</sup> intention</strong> pour préciser la sensibilisation, notamment en cas de <strong>discordance</strong> entre les prick-tests et la clinique, de <strong>contre-indication aux prick-tests</strong>, ou de <strong>doute diagnostique</strong>. Le critère positif est un taux exprimé en kUA/L, considéré comme <strong>significatif à partir de ≥ 0,35 kUA/L</strong>.</p>"},{"i":"b7c958afb93e","n":186,"o":"186-6","u":"Diagnostic positif","t":"Connaître et hiérarchiser les différentes étapes du diagnostic des allergies respiratoires","q":"Quels examens ne doivent PAS être prescrits dans le diagnostic d'une allergie respiratoire et pourquoi ?","a":"<p>Les examens à <strong>ne PAS prescrire</strong> dans le diagnostic d'une allergie respiratoire sont les <strong>IgE totales sériques</strong> (totalement inutiles et non remboursées), la <strong>PNE sanguine</strong>, la <strong>tryptase sérique de base</strong> (sauf suspicion de mastocytose ou en aigu pour anaphylaxie peranesthésique), et les <strong>IgG spécifiques</strong>. Ces examens n'ont <strong>aucune indication</strong> pour le diagnostic d'allergie.</p>"},{"i":"f05a28987669","n":186,"o":"186-6","u":"Diagnostic positif","t":"Connaître et hiérarchiser les différentes étapes du diagnostic des allergies respiratoires","q":"Quand est-ce qu'un test de provocation est réalisé dans le diagnostic d'une allergie respiratoire et où doit-il être effectué ?","a":"<p>Un <strong>test de provocation</strong> est réalisé <strong>rarement</strong>, uniquement pour un diagnostic de certitude lorsque le bilan de première intention (anamnèse, prick-tests, IgE spécifiques) est <strong>insuffisant</strong> et qu'il existe un <strong>impact thérapeutique</strong>. Ces tests (nasaux ou bronchiques) doivent être effectués <strong>exclusivement en milieu spécialisé hospitalier</strong>.</p>"},{"i":"f87d5fab919a","n":186,"o":"186-6","u":"Diagnostic positif","t":"Connaître et hiérarchiser les différentes étapes du diagnostic des allergies respiratoires","q":"Quelle est la première étape du diagnostic d'une allergie respiratoire et quels sont les critères positifs ?","a":"<p>La première étape du diagnostic d'une allergie respiratoire est l'<strong>anamnèse</strong>. Elle doit mettre en évidence une <strong>association forte entre l'exposition à l'allergène et la survenue des symptômes</strong>. Les critères positifs incluent une <strong>réaction aiguë survenant en moins d'une heure</strong> après l'exposition, qui est <strong>non dose-dépendante</strong> et <strong>reproductible</strong> à chaque exposition.</p>"},{"i":"13e6ad0d26eb","n":186,"o":"186-7","u":"Diagnostic positif","t":"Connaître les principaux allergènes de l’allergie alimentaire IgE-dépendante","q":"Quels sont les principaux allergènes alimentaires IgE-dépendants chez l'adulte ?","a":"<p>Chez l'adulte, les principaux allergènes alimentaires IgE-dépendants sont :</p><ul><li>Les <strong>fruits à coque</strong> (pistache, noix de cajou, noisette, noix, amande)</li><li>Les <strong>fruits frais</strong> (pomme, poire, prune, pêche, abricot, kiwi)</li><li>Les <strong>crustacés</strong></li></ul>"},{"i":"3f7793a451c4","n":186,"o":"186-7","u":"Diagnostic positif","t":"Connaître les principaux allergènes de l’allergie alimentaire IgE-dépendante","q":"Quel est l'allergène alimentaire IgE-dépendante qui prédomine chez l'enfant après l'âge de 3 ans ?","a":"<p>Après l'âge de 3 ans, l'<strong>arachide</strong> prend la première place comme allergène alimentaire IgE-dépendante dominant chez l'enfant.</p>"},{"i":"4d213efa3179","n":186,"o":"186-7","u":"Diagnostic positif","t":"Connaître les principaux allergènes de l’allergie alimentaire IgE-dépendante","q":"Quels sont les principaux allergènes alimentaires IgE-dépendants chez l'enfant de moins de 1 an ?","a":"<p>Avant l'âge de 1 an, les principaux allergènes alimentaires IgE-dépendants chez l'enfant sont le <strong>lait de vache</strong> et l'<strong>œuf</strong>.</p>"}]};